// Второзаконня — Біблія, переклад Патріарха Філарета. Згенеровано scripts/build_bible.py, не правте вручну.
import type { BChap } from '../types';
const C: BChap[] = [{"v":["Це є слова, які говорив Мойсей усім ізраїльтянам за Йорданом у пустелі на рівнині навпроти Суфа, між Фараном і Тофелом, і Лаваном, і Асирофом, і Дизагавом,","на відстані одинадцяти днів путі від Хорива, по дорозі від гори Сеїр до Кадес-Варні.","Сорокового року, одинадцятого місяця, у перший [день] місяця говорив Мойсей [усім] синам Ізраїлевим усе, що заповів йому Господь про них.","Після вбивства ним Сигона, царя Аморрейського, який жив у Есевоні, і Ога, царя Васанського, який жив у Аштерофі в Едреї,","за Йорданом, у землі Моавитській, почав Мойсей пояснювати закон цей і сказав:","Господь, Бог наш, говорив нам у Хориві і сказав: «досить вам жити на горі цій!","поверніться, вирушайте в путь і підіть на гору аморреїв і до всіх сусідів їх, на рівнину, на гору, на низькі місця і на південний край і до берегів моря, у землю Ханаанську і до Ливану, навіть до ріки великої, ріки Євфрату;","ось, Я даю вам землю цю, підіть, візьміть у спадщину землю, яку Господь із клятвою обіцяв дати батькам вашим, Аврааму, Ісааку і Якову, їм і нащадкам їхнім».","І я сказав вам у той час: не можу один водити вас;","Господь, Бог ваш, розмножив вас, і ось, ви нині численні, як зірки небесні;","Господь, Бог отців ваших, нехай розмножить вас у тисячу разів проти того, скільки вас тепер, і хай благословить вас, як Він говорив вам:","як же мені одному носити тяготи ваші, тягарі ваші і суперечки ваші?","оберіть собі в колінах ваших мужів мудрих, розумних і випробуваних, і я поставлю їх начальниками вашими.","Ви відповіли мені і сказали: добру справу ти наказуєш зробити.","І взяв я старійшин із колін ваших, мужів мудрих, [розумних] і випробуваних, і зробив їх начальниками над вами, тисячоначальниками, стоначальниками, п’ятдесятиначальниками, десятиначальниками і наглядачами за колінами вашими.","І дав я повеління суддям вашим у той час, говорячи: вислуховуйте братів ваших і судіть справедливо, як брата з братом, так і прибулого його;","не розрізняйте осіб на суді, як малого, так і великого вислуховуйте: не бійтеся лиця людського, тому що суд — справа Божа.","І дав я вам у той час повеління про все, що слід вам робити.","І вирушили ми від Хорива, і йшли по всій цій великій і страшній пустелі, яку ви бачили, по шляху до гори Аморрейської, як повелів Господь, Бог наш, і прийшли в Кадес-Варні.","І сказав я вам: ви прийшли до гори Аморрейської, яку Господь, Бог наш, дає нам;","ось, Господь, Бог твій, віддає тобі землю цю, йди, візьми її у володіння, як говорив тобі Господь, Бог батьків твоїх, не бійся і не жахайся.","Але ви усі підійшли до мене і сказали: пошлемо перед собою людей, щоб вони дослідили нам землю і принесли нам звістку про дорогу, по якій іти нам, і про міста, в які йти нам.","Слово це мені сподобалося, і я взяв з вас дванадцять мужів, по одній людині від [кожного] коліна.","Вони пішли, зійшли на гору і дійшли до долини Есхол, і оглянули її;","і взяли в руки свої плоди землі і доставили нам, і принесли нам звістку і сказали: добра земля, яку Господь, Бог наш, дає нам.","Але ви не захотіли йти і стали проти веління Господа, Бога вашого,","і нарікали в наметах ваших і говорили: Господь, з ненависти до нас, вивів нас із землі Єгипетської, щоб віддати нас у руки аморреїв і знищити нас;","куди ми підемо? брати наші розслабили серце наше, говорячи: народ той більший, [численніший] і вищій за нас, міста там великі і з укріпленнями до небес, та й синів Енакових бачили ми там.","І я сказав вам: не страшіться і не бійтеся їх;","Господь, Бог ваш, іде перед вами; Він буде боротися за вас, як Він зробив з вами в Єгипті, перед очима вашими,","і в пустелі цій, де, як ти бачив, Господь, Бог твій, носив тебе, як людина носить сина свого, на всьому шляху, яким ви проходили, до приходу вашого на це місце.","Але і при цьому ви не вірили Господу, Богу вашому,","Який ішов перед вами шляхом — шукати вам місце, де зупинитися вам, вночі у вогні, щоб указувати вам дорогу, по якій іти, а вдень у хмарі.","І Господь [Бог] почув слова ваші, і розгнівався, і поклявся, говорячи:","ніхто з людей цих, з цього злого роду, не побачить доброї землі, яку Я клявся дати батькам вашим;","тільки Халев, син Ієфонніїн, побачить її; йому дам Я землю, по якій він проходив, і синам його, за те, що він підкорився Господу.","І на мене прогнівався Господь за вас, говорячи: і ти не ввійдеш туди;","Ісус, син Навина, який при тобі, він увійде туди; його утверди, тому що він введе Ізраїля у володіння нею;","діти ваші, про яких ви говорили, що вони дістануться у здобич ворогам, і сини ваші, які не знають нині ні добра ні зла, вони ввійдуть туди, їм дам її, і вони оволодіють нею;","а ви поверніться і рушайте в пустелю по дорозі до Червоного моря.","І ви відповіли тоді і сказали мені: згрішили ми перед Господом, [Богом нашим,] підемо й будемо воювати, як повелів нам Господь, Бог наш. І підперезалися ви, кожен військовою зброєю своєю, і нерозсудливо зважилися зійти на гору.","Але Господь сказав мені: скажи їм: не піднімайтесь і не воюйте, тому що немає Мене серед вас, щоб не уразили вас вороги ваші.","І я говорив вам, але ви не послухали і стали проти веління Господнього і з упертості своєї зійшли на гору.","І виступив проти вас Аморрей, який жив на горі тій, і переслідували вас так, як роблять бджоли, й уражали вас на Сеїрі до самої Хорми.","І повернулися ви і плакали перед Господом: але Господь не почув волання вашого і не послухав вас.","І пробули ви в Кадесі багато часу, скільки часу ви там були."],"x":{"1":"3.33.8","2":"1.3.1","4":"3.21.24","6":"1.19.1|3.10.11","7":"0.2.14|0.15.18","8":"0.12.7|0.15.18|0.17.8","9":"1.18.18|3.11.14","10":"0.15.5","15":"1.18.25|3.11.16","16":"53.7.24","17":"4.16.19|56.1.17|2.19.15|26.24.23|30.42.1|55.2.1","19":"3.13.1:27","21":"5.8.1","22":"3.13.3-4","24":"3.13.24","25":"3.13.28","27":"3.14.2|25.105.24-25","28":"3.32.9|0.11.4","29":"5.2.9","30":"1.14.14:25|5.10.14","31":"1.19.4|3.11.18|25.90.12","32":"25.77.32|75.3.18-19","33":"1.13.21","35":"3.14.23|3.26.65|75.3.11","37":"3.20.12|4.3.26|4.4.21|4.31.2","38":"4.3.28|3.34.17|5.1.6","39":"3.14.31|42.4.11","40":"3.14.25","41":"3.14.40","42":"4.23.14","43":"3.14.41:44","44":"3.14.45|25.117.12|5.19.4","46":"4.2.14"}},{"v":["І повернули ми і вирушили в пустелю до Червоного моря, як говорив мені Господь, і багато часу ходили навколо гори Сеїра.","І сказав мені Господь, говорячи:","досить вам ходити навколо цієї гори, поверніть на північ;","і народу дай повеління і скажи: ви будете проходити межі братів ваших, синів Ісавових, які живуть на Сеїрі, і вони убояться вас; але остерігайтеся","починати з ними війну, бо Я не дам вам землі їх ні на стопу ноги, тому що гору Сеїр Я дав у володіння Ісаву;","їжу купуйте в них за срібло і їжте; і воду купуйте в них за срібло і пийте;","бо Господь, Бог твій, благословив тебе у всякій справі рук твоїх, був покровителем тобі під час подорожі твоєї по великій [і страшній] пустелі цій; ось, сорок років Господь, Бог твій, з тобою; ти ні в чому не терпів нестачі.","І йшли ми повз братів наших, синів Ісавових, які живуть на Сеїрі, шляхом рівнини, від Елафа й Ецион-Гавера, і повернули, і йшли до пустелі Моава.","І сказав мені Господь: не вступай у ворожнечу з Моавом і не починай з ними війни; бо Я не дам тобі нічого від землі його у володіння, тому що Ар віддав Я у володіння синам Лотовим;","раніше жили там емими, народ великий, численний і високий, як сини Енакові,","і вони вважалися між рефаїмами, як сини Енакові; моавитяни ж називають їх емимами;","а на Сеїрі жили колись хорреї; але сини Ісавові прогнали їх і знищили їх від лиця свого й оселилися замість них — так, як вчинив Ізраїль із землею спадщини своєї, яку дав їм Господь;","отже, встаньте і пройдіть долину Заред. І пройшли ми долину Заред.","З тих пір, як ми пішли в Кадес-Варні і як пройшли долину Заред, минуло тридцять вісім років, і в нас перевівся з середовища стану весь рід, що ходить на війну, як клявся їм Господь [Бог];","та й рука Господня була на них, щоб винищувати їх із середовища стану, поки не вимерли.","Коли ж перевелися всі, що ходять на війну, і вимерли із середовища народу,","тоді сказав мені Господь, говорячи:","ти проходиш нині повз межі Моава, мимо Ара,","і наблизився до аммонитян; не вступай з ними у ворожнечу, і не починай з ними війни, бо Я не дам тобі нічого від землі синів Аммонових у володіння, бо Я віддав її в володіння синам Лотовим;","і вона вважалася землею рефаїмів; раніше жили на ній рефаїми; аммонитяни ж називають їх замзумимами;","народ великий, численний і високий, як сини Енакові, і знищив їх Господь перед лицем їх, і вигнали вони їх і оселилися на місці їхньому,","як Він зробив для синів Ісавових, які живуть на Сеїрі, знищивши перед лицем їх хорреїв, і вони вигнали їх, і оселилися на місці їх, і живуть до цього дня;","і аввеїв, які жили в селищах до самої Гази, Кафторими, що вийшли з Кафтора, знищили й оселилися на місці їх.","Встаньте, рушайте і перейдіть потік Арнон; ось, Я віддаю в руки твої Сигона, царя Есевонського, аморреянина, і землю його; починай оволодівати нею, і веди з ним війну;","з цього дня Я почну поширювати страх і жах перед тобою на народи під усім небом; ті, які почують про тебе, затремтять і жахнуться тебе.","І послав я послів з пустелі Кедемоф до Сигона, царя Есевонського, зі словами мирними, щоб сказати:","дозволь пройти мені землею твоєю; я піду дорогою, не зійду ні праворуч, ні ліворуч;","їжу продавай мені за срібло, і я буду їсти, і воду для пиття давай мені за срібло, і я буду пити, тільки ногами моїми пройду","так, як зробили мені сини Ісава, які живуть на Сеїрі, і моавитяни, які живуть в Арі, доки не перейду через Йордан у землю, яку Господь, Бог наш, дає нам.","Але Сигон, цар Есевонський, не погодився дозволити пройти нам через свою землю, тому що Господь, Бог твій, озлобив дух його і серце його зробив упертим, щоб віддати його в руку твою, як це видно нині.","І сказав мені Господь: ось, Я починаю віддавати тобі Сигона [царя Есевонського, аморреянина,] і землю його; починай оволодівати землею його.","І Сигон [цар Есевонський] із усім народом своїм виступив проти нас на бій до Яаца;","і віддав його Господь, Бог наш, [у руки наші,] і ми подолали його і синів його і весь народ його,","і взяли в той час усі міста його, і віддали закляттю всі міста, чоловіків і жінок і дітей, не залишили нікого в живих;","тільки взяли ми собі у здобич худобу їхню і захоплене у взятих нами містах.","Від Ароера, що на березі потоку Арнона, і від міста, що на долині, до [гори] Галаада не було міста, яке було б неприступним для нас: усе віддав Господь, Бог наш, [у руки наші].","Тільки до землі аммонитян ти не підходив, ні до місць [що лежать] біля потоку Іавока, ні до міст [які] на горі, ні до усього, до чого не повелів [нам] Господь, Бог наш."],"x":{"1":"3.21.4","3":"6.5.4","4":"3.20.14:21","5":"8.14.47|9.8.14|10.11.15","7":"4.1.31|0.21.22","8":"11.14.22|10.9.26","9":"13.20.10","10":"0.14.5|3.13.23","12":"0.14.6|0.36.20","13":"3.21.12","14":"4.1.46|3.26.65","19":"6.11.13:15|0.19.38","21":"3.13.23","23":"0.10.14|32.47.4|40.9.7","25":"5.2.9","26":"3.21.21","28":"3.20.19","30":"3.20.20|3.21.23|1.4.21","31":"40.2.9","33":"3.21.24","34":"4.3.6|4.13.15|4.20.16","36":"9.24.5|3.21.15"}},{"v":["І повернули ми звідти, і йшли до Васана, і виступив проти нас на війну Ог, цар Васанський, з усім народом своїм, при Едреї.","І сказав мені Господь: не бійся його, тому що Я віддам у руку твою його, і весь народ його, і всю землю його, і ти вчиниш з ним так, як вчинив із Сигоном, царем Аморрейським, який жив у Есевоні","І віддав Господь, Бог наш, у руки наші й Ога, царя Васанського, і весь народ його; і ми подолали його, так що нікого не залишилося в нього в живих;","і взяли ми в той час усі міста його; не було міста, яке ми не взяли б у них: шістдесят міст, усю область Аргов, царство Ога Васанського;","усі ці міста укріплені були високими стінами, воротами і запорами, крім міст неукріплених, дуже багатьох;","і піддали ми їх закляттю, як вчинили із Сигоном, царем Есевонським, піддавши закляттю всяке місто з чоловіками, жінками і дітьми;","але вся худоба і захоплене в містах взяли собі у здобич.","І взяли ми в той час з руки двох царів аморрейських землю цю, яка по цю сторону Йордану, від потоку Арнона до гори Ермона, —","сидоняни Ермон називають Сирионом, а аморреї називають його Сениром, —","усі міста на рівнині, весь Галаад і весь Васан до Салхи та Едреї, міста? царства Ога Васанського;","бо тільки Ог, цар Васанський, залишався з рефаїмів. Ось, одр його, одр залізний, і тепер у Равві, у синів Аммонових: довжина його дев’ять ліктів, а ширина його чотири лікті, ліктів чоловічих.","Землю цю взяли ми в той час, починаючи від Ароера, що біля потоку Арнона; і половину гори Галаада з містами її віддав я коліну Рувимовому і Гадовому;","а залишок Галаада і весь Васан, царство Ога, віддав я половині коліна Манассіїного, всю область Аргов з усім Васаном. [Вона називається землею рефаїмів.]","Яїр, син Манассіїн, узяв усю область Аргов, до меж Гесурських і Маахських, і назвав Васан, за іменем своїм, селищами Яїровими, що і донині;","Махиру дав я Галаад;","а коліну Рувимовому і Гадовому дав від Галаада до потоку Арнона, землю між потоком і межею, до потоку Іавока, межі синів Аммонових,","також рівнину і Йордан, який є і межа, від Киннерефа до моря рівнини, моря Солоного, біля підошви гори Фасги на схід.","І дав я вам у той час повеління, говорячи: Господь, Бог ваш, дав вам землю цю у володіння; усі здатні до війни, озброївшись, ідіть попереду братів ваших, синів Ізраїлевих;","тільки дружини ваші і діти ваші і худоба ваша [бо я знаю, що худоби у вас багато,] нехай залишаться в містах ваших, які я дав вам,","доки Господь [Бог] не дасть спокою братам вашим, як вам, і доки й вони не одержать у володіння землю, яку Господь, Бог ваш, дає їм за Йорданом; тоді поверніться кожен у своє володіння, яке я дав вам.","І Ісусові заповів я в той час, говорячи: очі твої бачили усе, що зробив Господь, Бог ваш, із двома царями цими; те саме зробить Господь із усіма царствами, які ти будеш проходити;","не бійтеся їх, бо Господь, Бог ваш, Сам воює за вас.","І молився я Господу в той час, говорячи:","Владико Господи, Ти почав показувати рабові Твоєму велич Твою [і силу Твою, ] і міцну руку Твою [і могутність]; бо який бог є на небі, або на землі, який міг би робити такі справи, як Твої, і з могутністю такою, як Твоя?","дай мені перейти і побачити ту добру землю, яка за Йорданом, і ту чудову гору і Ливан.","Але Господь гнівався на мене за вас і не послухав мене, і сказав мені Господь: досить тобі, надалі не говори Мені більше про це;","зійди на вершину Фасги і подивись очима твоїми до моря і на північ, і на південь і на схід, і подивися очима твоїми, тому що ти не перейдеш за Йордан цей;","і дай настанови Ісусові, й укріпи його, й утверди його; тому що він буде передувати народу цьому і він розділить їм на наділи [усю] землю, на яку ти подивишся.","І зупинилися ми в долині, навпроти Беф-Фегора."],"x":{"1":"3.21.33|4.29.7","2":"3.21.24:34","3":"3.21.35","6":"4.2.34-35|4.20.16","7":"4.20.14","8":"3.34.7","9":"36.27.5","11":"3.21.31:33|5.12.13|9.12.26","12":"3.32.33","14":"3.32.41|10.4.13|9.10.6","15":"0.50.23|3.32.39","16":"0.32.22","17":"3.34.11-12|5.12.3","19":"3.32.1","22":"1.14.14:25|4.1.30|5.23.10","24":"10.8.42|25.67.8|25.88.7","25":"10.4.33","26":"4.1.37|4.4.21","27":"4.31.2","28":"4.1.38|5.1.6|5.14.1"}},{"v":["Отже, Ізраїлю: слухай постанови і закони, які Я [сьогодні] навчаю вас виконувати, щоб ви були живі [і розмножилися], і пішли й успадкували ту землю, яку Господь, Бог батьків ваших, дає вам [у спадок];","не додавайте до того, що Я заповідаю вам, і не вкорочуйте від того; зберігайте заповіді Господа, Бога нашого, які Я вам [сьогодні] заповідаю.","Очі ваші бачили [все], що зробив Господь [Бог наш] з Ваал-Фегором; усяку людину, яка пішла за Ваал-Фегором, знищив Господь, Бог твій, із середовища твого;","а ви, що приліпилися до Господа, Бога вашого, живі всі донині.","Ось, я навчив вас постанов і законів, як повелів мені Господь, Бог мій, щоб ви так чинили в тій землі, в яку ви вступаєте, щоб оволодіти нею;","отже, зберігайте і виконуйте їх, бо в цьому мудрість ваша і розум ваш перед очима народів, які, почувши про всі ці настанови, скажуть: тільки цей великий народ розумний.","Бо чи є який великий народ, до якого боги його були б такими близькими, як близький до нас Господь, Бог наш, коли тільки прикличемо Його?","і чи є який великий народ, у якого були б такі справедливі постанови і закони, як весь закон цей, який я пропоную вам сьогодні?","Тільки пильнуй і добре бережи душу твою, щоб тобі не забути тих діл, які бачили очі твої, і щоб вони не виходили з серця твого в усі дні життя твого; і передай це синам твоїм і синам синів твоїх, —","про той день, коли ти стояв перед Господом, Богом твоїм, при Хориві, [в день зібрання,] і коли сказав Господь мені: збери до Мене народ, і Я сповіщу йому слова Мої, з яких вони навчаться боятися Мене в усі дні життя свого на землі і навчать синів своїх.","Ви наблизилися і стали під горою, і гора горіла вогнем до самих небес, і були темрява, хмара і морок.","І говорив Господь Бог до вас [на горі] з середовища полум’я; глас слів [Його] ви чули, але образа не бачили, а тільки глас;","і оголосив Він вам завіт Свій, який повелів вам виконувати, десятислів’я, і написав його на двох кам’яних скрижалях;","і повелів мені Господь у той час навчити вас постанов і законів, щоб ви виконували їх у тій землі, в яку ви входите, щоб оволодіти нею.","Твердо дотримуйте в душах ваших, що ви не бачили ніякого образа в той день, коли промовляв до вас Господь на [горі] Хориві з середовища вогню,","щоб ви не розбестилися і не зробили собі статуй, зображень якого-небудь кумира, що представляють чоловіка або жінку,","зображення якої-небудь худоби, що на землі, зображення якого-небудь птаха крилатого, який літає під небесами,","зображення якого-небудь [гада,] що плазує по землі, зображення якої-небудь риби, що у водах нижче землі;","і щоб ти, глянувши на небо і побачивши сонце, місяць і зірки [й] усе воїнство небесне, не спокусився і не поклонився їм і не служив їм, оскільки Господь, Бог твій, віддав їх усім народам під усім небом.","А вас узяв Господь [Бог] і вивів вас із печі залізної, з Єгипту, щоб ви були народом Його наділу, як це нині видно.","І Господь [Бог] прогнівався на мене за вас, і клявся, що я не перейду за Йордан і не ввійду в ту добру землю, яку Господь, Бог твій, дає тобі в наділ;","я помру в цій землі, не перейшовши за Йордан, а ви перейдете й оволодієте тою доброю землею.","Бережіться, щоб не забули ви завіту Господа, Бога вашого, який Він склав з вами, і щоб не робити собі ідолів, які зображають що-небудь, як повелів тобі Господь, Бог твій;","бо Господь, Бог твій, є вогонь, що поїдає, Бог ревнитель.","Якщо ж народяться у тебе сини і сини у синів [твоїх], і, довго живучи на землі, ви розбеститеся і зробите ідола, що зображає що-небудь, і зробите зло це перед очима Господа, Бога вашого, і роздратуєте Його,","то засвідчую вам сьогодні небом і землею, що незабаром втратите землю, для успадкування якої ви переходите за Йордан; не пробудете багато часу на ній, але загинете;","і розсіє вас Господь по [усіх] народах, і залишитеся в малому числі між народами, до яких відведе вас Господь;","і будете там служити [іншим] богам, зробленим руками людськими з дерева і каменю, які не бачать і не чують, і не їдять і не нюхають.","Але коли ти шукатимеш там Господа, Бога твого, то знайдеш [Його], якщо будеш шукати Його всім серцем твоїм і всією душею твоєю.","Коли ти будеш у скорботі, і коли все це осягне тебе впродовж часу, то звернешся до Господа, Бога твого, і послухаєш гласу Його.","Господь, Бог твій, є Бог [благий і] милосердий; Він не залишить тебе і не погубить тебе, і не забуде завіту з батьками твоїми, який Він клятвою утвердив їм.","Бо запитай у часів минулих, що були раніше тебе, з того дня, в який створив Бог людину на землі, і від краю неба до краю неба: чи бувало що-небудь таке, як ця велика справа, або чи чули щось подібне до цього?","чи чув [який] народ глас Бога [живого], Який говорить із середовища вогню, і залишився живим, як чув ти?","або чи намагався який бог піти, взяти собі народ із середовища іншого народу покараннями, знаменнями і чудесами, і війною, і рукою міцною, і силою великою, і великими жахами, як зробив для вас Господь, Бог ваш, у Єгипті перед очима твоїми?","Тобі дано бачити це, щоб ти знав, що тільки Господь [Бог твій] є Бог, [і] немає іншого, крім Нього;","з неба дав Він чути тобі глас Свій, щоб навчити тебе, і на землі показав тобі великий вогонь Свій, і ти чув слова Його із середовища вогню;","і тому що Він полюбив батьків твоїх і обрав [вас,] нащадків їхніх після них, то і вивів тебе Сам великою силою Своєю з Єгипту,","щоб прогнати від лиця твого народи, які більші і сильніші за тебе, і ввести тебе і дати тобі землю їхню в наділ, як це нині видно.","Отже, знай нині і поклади на серце твоє, що Господь [Бог твій] є Бог на небі вгорі і на землі внизу, [і] немає ще [крім Нього];","і зберігай постанови Його і заповіді Його, які я заповідаю тобі нині, щоб добре було тобі і синам твоїм після тебе, і щоб ти багато часу прожив на тій землі, яку Господь, Бог твій, дає тобі назавжди.","Тоді відокремив Мойсей три міста по цей бік Йордану на схід сонця,","щоб тікав туди убивця, який уб’є ближнього свого без наміру, не бувши ворогом його ні вчора, ні третього дня, і щоб, утікши в одне з цих міст, залишився живим:","Бецер у пустелі, на рівнині в коліні Рувимовому, і Рамоф у Галааді в коліні Гадовому, і Голан у Васані в коліні Манассіїному.","Ось закон, який запропонував Мойсей синам Ізраїлевим;","ось повеління, постанови й устави, які проголосив Мойсей синам Ізраїлевим [у пустелі], після виходу їх з Єгипту,","за Йорданом, у долині навпроти Беф-Фегора, в землі Сигона, царя Аморрейського, що жив у Есевоні, якого подолав Мойсей із синами Ізраїлевими, після виходу їх з Єгипту.","І оволоділи вони землею його і землею Ога, царя Васанського, двох царів аморрейських, що за Йорданом на схід сонця,","починаючи від Ароера, що лежить на березі потоку Арнона, до гори Сиону, вона ж Ермон,","і всією рівниною по цей бік Йордану на схід, до самого моря рівнини біля підошви Фасги."],"x":{"1":"4.12.32","2":"4.12.32|26.30.6","3":"3.25.4|5.22.17|25.105.28","6":"16.14.30","7":"4.26.19|25.144.18|25.146.9","8":"10.2.3|25.118.98","9":"25.76.12|25.104.5|4.11.19","10":"16.3.17","11":"1.19.18","12":"17.9.13|53.1.18","13":"1.20.1|64.3.3","15":"5.23.11|32.17.21","16":"1.20.4","17":"62.1.23","19":"32.10.2|4.17.3|50.5.45","20":"30.17.13","21":"4.1.37|4.3.27|4.34.4|3.20.12","22":"4.34.4-5","23":"29.1.12","24":"75.12.29","26":"4.30.19|4.31.28|4.32.1","27":"4.28.64|0.34.30","28":"4.28.36","29":"25.114.4-5|29.1.2","30":"2.26.40","31":"25.102.8|31.11.12","33":"1.19.18-19|1.20.1|4.5.23","34":"4.7.19|4.29.3|1.13.3:9","35":"1.19.16|4.32.39|10.8.60","37":"1.13.3","39":"5.2.11","40":"4.5.33|4.6.3","41":"4.19.2","42":"3.35.6","43":"5.20.8","46":"4.1.4-5|4.3.29|3.21.24","47":"3.21.24:33|4.29.7-8","48":"3.34.7|4.3.9"}},{"v":["І скликав Мойсей увесь Ізраїль і сказав їм: слухай, Ізраїлю, постанови і закони, які я проголошу сьогодні у вуха ваші, і вивчіть їх і намагайтеся виконувати їх.","Господь, Бог наш, уклав з нами завіт на Хориві;","не з батьками нашими уклав Господь завіт цей, але з нами, які тут сьогодні усі живі.","Лицем до лиця говорив Господь з вами на горі із середовища вогню;","я ж стояв між Господом і між вами в той час, щоб переказувати вам слово Господа, бо ви боялися вогню і не піднімалися на гору. Він тоді сказав:","Я Господь, Бог твій, Який вивів тебе з землі Єгипетської, з дому рабства;","нехай не буде в тебе інших богів перед лицем Моїм.","Не роби собі ідола і ніякого зображення того, що на небі вгорі і що на землі внизу, і що у водах нижче землі,","не поклоняйся їм і не служи їм; тому що Я Господь, Бог твій, Бог ревнитель, Той, що карає за провину батьків дітей до третього і четвертого роду, які ненавидять Мене,","і Той, що творить милість до тисячі родів тих, що люблять Мене і дотримують заповідей Моїх.","Не вживай імені Господа, Бога твого, марно; тому що не залишить Господь [Бог твій] без покарання того, хто вживає ім’я Його марно.","Пильнуй день суботній, щоб свято зберігати його, як заповів тобі Господь, Бог твій;","шість днів працюй і роби всякі діла твої,","а день сьомий — субота Господу, Богу твоєму. Не роби [в ньому] ніякої справи, ні ти, ні син твій, ні дочка твоя, ні раб твій, ні раба твоя, ні віл твій, ні осел твій, ні всяка худоба твоя, ні прибулець твій, який у тебе, щоб відпочив раб твій, і раба твоя [і осел твій,] як і ти;","і пам’ятай, що [ти] був рабом у землі Єгипетській, але Господь, Бог твій, вивів тебе звідти рукою міцною і силою великою, тому і повелів тобі Господь, Бог твій, дотримувати дня суботнього [і свято зберігати його].","Шануй батька твого і матір твою, як повелів тобі Господь, Бог твій, щоб продовжилися дні твої, і щоб добре тобі було на тій землі, яку Господь, Бог твій, дає тобі.","Не вбивай.","Не перелюбствуй.","Не кради.","Не лжесвідчи на ближнього твого.","Не бажай дружини ближнього твого і не бажай дому ближнього твого, ні поля його, ні раба його, ні рабині його, ні вола його, ні осла його, [ні всякої худоби його,] ні всього, що є у ближнього твого.","Слова ці проголосив Господь до всього зібрання вашого на горі із середовища вогню, хмари і мороку [і бурі] гучноголосо, і більше не говорив, і написав їх на двох кам’яних скрижалях, і дав їх мені.","І коли ви почули голос із середовища мороку, і гора горіла вогнем, то ви підійшли до мене, усі начальники колін ваших і старійшини ваші,","і сказали: ось, показав нам Господь, Бог наш, славу Свою і велич Свою, і голос Його ми чули із середовища вогню; сьогодні бачили ми, що Бог говорить з людиною, і вона залишається живою;","але тепер для чого нам помирати? бо цей великий вогонь спалить нас; якщо ми ще почуємо глас Господа, Бога нашого, то помремо,","бо чи є яка плоть, яка чула б глас Бога живого, Який говорить із середовища вогню, як ми, і залишилася живою?","приступи ти і слухай усе, що скаже [тобі] Господь, Бог наш, і ти переказуй нам усе, що буде говорити тобі Господь, Бог наш, і ми будемо слухати і виконувати.","І Господь почув слова ваші, як ви розмовляли зі мною, і сказав мені Господь: чув Я слова народу цього, які вони говорили тобі; усе, що говорили вони, добре;","о, якби серце їх було у них таке, щоб боятися Мене і дотримувати всіх заповідей Моїх у всі дні, щоб добре було їм і синам їхнім повік!","піди, скажи їм: «поверніться в намети свої»;","а ти залишся тут зі Мною, і Я проголошу тобі всі заповіді і постанови і закони, яких ти повинен навчити їх, щоб вони [так] чинили на тій землі, яку Я даю їм у володіння.","Дивіться, чиніть так, як повелів вам Господь, Бог ваш; не ухиляйтеся ні праворуч, ні ліворуч;","ходіть тією дорогою, якою повелів вам Господь, Бог ваш, щоб ви були живими, і добре було вам, і прожили багато часу на тій землі, яку одержите у володіння."],"x":{"1":"26.4.4","2":"1.19.5","3":"0.17.2","4":"1.19.16|1.20.1|1.33.11","5":"65.3.19","6":"1.20.2|25.80.11","8":"1.20.4|2.26.1|25.96.7","9":"1.20.5|1.34.7|32.32.18","10":"1.20.6|1.34.7|32.32.18","11":"1.20.7|2.19.12|50.5.33","12":"1.20.8|1.31.14|32.20.12","13":"1.20.9|2.23.3","14":"1.20.10|75.4.4","15":"4.16.12|32.21.5","16":"1.20.12|30.3.6|50.15.4|51.7.10|66.6.2-3","17":"1.20.13|50.5.21:27|50.19.18","21":"1.20.17|62.7.7|62.13.9","22":"1.20.1","23":"1.20.18","24":"1.33.20","25":"1.20.19|6.13.22","26":"4.4.33|31.6.5|31.40.6","27":"1.19.8","28":"29.1.6|4.18.17","29":"25.80.14|31.48.18","32":"4.17.11|4.28.14","33":"0.18.19|10.3.2"}},{"v":["Ось заповіді, постанови і закони, яких повелів Господь, Бог ваш, навчити вас, щоб ви чинили [так] у тій землі, в яку ви йдете, щоб оволодіти нею;","щоб ти боявся Господа, Бога твого, і всіх постанов Його і заповідей Його, які [сьогодні] заповідаю тобі, дотримував ти і сини твої і сини синів твоїх в усі дні життя твого, щоб продовжилися дні твої.","Отже, слухай, Ізраїлю, і намагайся виконати це, щоб тобі добре було, і щоб ви дуже розмножилися, як Господь, Бог батьків твоїх, говорив тобі, [що Він дасть тобі] землю, де тече молоко і мед. [Це є постанови і закони, які заповів Господь Бог синам Ізраїлевим у пустелі, після виходу їх із землі Єгипетської.]","Слухай, Ізраїлю: Господь, Бог наш, Господь єдиний є;","і люби Господа, Бога твого, усім серцем твоїм, і всією душею твоєю і всіма силами твоїми.","І нехай будуть слова ці, які Я заповідаю тобі сьогодні, у серці твоєму [і в душі твоїй];","і навчай їх дітей твоїх і говори про них, сидячи в домі твоєму і йдучи дорогою, і лягаючи і встаючи;","і нав’яжи їх в ознаку на руку твою, і нехай будуть вони пов’язкою над очима твоїми,","і напиши їх на одвірках дому твого і на воротах твоїх.","Коли ж введе тебе Господь, Бог твій, у ту землю, яку Він клявся батькам твоїм, Аврааму, Ісааку і Якову, дати тобі з великими і добрими містами, яких ти не будував,","і з домами, наповненими всяким добром, яких ти не наповнював, і з колодязями, висіченими з каменю, яких ти не висікав, з виноградниками і маслинами, яких ти не садив, і будеш їсти і насичуватися,","тоді бережися, щоб [не спокусилося серце твоє і] не забув ти Господа, Який вивів тебе з землі Єгипетської, з дому рабства.","Господа, Бога твого, бійся, і Йому [одному] служи, [і до Нього приліпись,] і Його ім’ям клянися.","Не йдіть за іншими богами, богами тих народів, які будуть навколо вас;","тому що Господь, Бог твій, Який посеред тебе, є Бог ревнитель; щоб не запалав гнів Господа, Бога твого, на тебе, і не знищив Він тебе з лиця землі.","Не спокушайте Господа, Бога вашого, як ви спокушали Його в Массі.","Твердо зберігайте заповіді Господа, Бога вашого, й устави Його і постанови, які Він заповів тобі;","і роби справедливе і добре перед очима Господа [Бога твого], щоб добре тобі було, і щоб ти ввійшов і оволодів доброю землею, яку Господь з клятвою обіцяв батькам твоїм,","і щоб Він прогнав усіх ворогів твоїх від лиця твого, як говорив Господь.","Якщо запитає в тебе син твій у майбутній час, говорячи: «що означають ці устави, постанови і закони, які заповів вам Господь, Бог ваш?»","то скажи синові твоєму: «рабами були ми у фараона в Єгипті, але Господь [Бог] вивів нас з Єгипту рукою міцною [і силою великою],","і показав Господь [Бог] знамення і чудеса великі і кари над Єгиптом, над фараоном і над усім домом його [і над військом його] перед очима нашими;","а нас вивів звідти [Господь, Бог наш,] щоб ввести нас і дати нам землю, яку [Господь, Бог наш,] клявся батькам нашим [дати нам];","і заповів нам Господь виконувати всі постанови ці, щоб ми боялися Господа, Бога нашого, щоб добре було нам в усі дні, щоб зберегти наше життя, як і тепер;","і в цьому буде наша праведність, якщо ми будемо намагатися виконувати всі ці заповіді [закону] перед лицем Господа, Бога нашого, як Він заповів нам."],"x":{"1":"55.1.22","2":"4.4.40","4":"51.12.29","5":"50.22.37|51.12.30|52.10.27","6":"4.4.9","7":"4.30.19|25.77.5-6","10":"0.50.24|1.33.1","11":"4.8.10","13":"4.10.20|8.7.3|50.4.10|52.4.8","14":"1.20.2-3","16":"1.17.2|3.21.5|50.4.7|52.4.12","18":"0.12.7|0.13.15","19":"1.23.27","20":"1.12.26","21":"1.1.11:14|1.12.37|1.13.3","24":"25.66.7","25":"2.18.5|36.20.11|50.19.17"}},{"v":["Коли введе тебе Господь, Бог твій, у землю, в яку ти йдеш, щоб оволодіти нею, і прожене від лиця твого численні народи, хеттеїв, гергесеїв, аморреїв, хананеїв, ферезеїв, евеїв та ієвусеїв, сім народів, які численніші і сильніші за тебе,","і видасть їх тобі Господь, Бог твій, і уразиш їх, тоді піддай їх закляттю, не вступай з ними в союз і не жалій їх;","і не вступай з ними у споріднення: дочки твоєї не віддавай за сина його, і дочки його не бери за сина твого;","тому що вони відвернуть синів твоїх від Мене, щоб служити іншим богам, і тоді запалає на вас гнів Господа, і Він незабаром знищить тебе.","Але вчиніть з ними так: жертовники їх зруйнуйте, стовпи їх розтрощіть, і діброви їх вирубайте, й ідолів [богів] їх спаліть вогнем;","бо ти народ святий у Господа, Бога твого: тебе обрав Господь, Бог твій, щоб ти був власним Його народом з усіх народів, які на землі.","Не тому, щоб ви були найчисленнішими за всі народи, прийняв вас Господь і обрав вас, — бо ви нечисленніші за всі народи, —","але тому, що любить вас Господь, і для того, щоб зберегти клятву, якою Він клявся батькам вашим, вивів вас Господь рукою міцною [і силою великою] і звільнив тебе з дому рабства, з руки фараона, царя Єгипетського.","Отже, знай, що Господь, Бог твій, є Бог, Бог вірний, Який зберігає завіт [Свій] і милість до тих, що люблять Його і зберігають заповіді Його до тисячі родів,","і відплачує ненависникам Його в особі їх, погублюючи їх; Він не забариться, ненависнику Його самому особисто віддасть.","Отже, дотримуй заповідей і постанов і законів, які сьогодні заповідаю тобі виконувати.","І якщо ви будете слухати закони ці і зберігати і виконувати їх, то Господь, Бог твій, буде зберігати завіт і милість до тебе, як Він клявся батькам твоїм,","і полюбить тебе, і благословить тебе, і розмножить тебе, і благословить плід утроби твоєї і плід землі твоєї, і хліб твій, і вино твоє, і єлей твій, народжуване від великої худоби твоєї і від отари овець твоїх, на тій землі, яку Він клявся батькам твоїм дати тобі;","благословенний ти будеш більше за всі народи; не буде ні неплідного, ні неплідної, ні в тебе, ні в худобі твоїй;","і віддалить від тебе Господь [Бог твій] усяку неміч, і ніяких лютих хвороб єгипетських, [які ти бачив і] які ти знаєш, не наведе на тебе, але наведе їх на всіх, що ненавидять тебе;","і знищиш усі народи, які Господь, Бог твій, дає тобі: нехай не пощадить їх око твоє; і не служи богам їх, бо це тенети для тебе.","Якщо скажеш у серці твоєму: «народи ці численніші за мене; як я можу вигнати їх?»","Не бійся їх, згадай те, що зробив Господь, Бог твій, з фараоном і всім Єгиптом,","ті великі випробування, які бачили очі твої, [великі] знамення, чудеса, і руку міцну і силу велику, з якими вивів тебе Господь, Бог твій; те саме зробить Господь, Бог твій, із усіма народами, яких ти боїшся;","і шершнів нашле Господь, Бог твій, на них, доки не загинуть ті, що залишилися і сховалися від лиця твого;","не страшися їх, бо Господь, Бог твій, з тобою, Бог великий і страшний.","І буде Господь, Бог твій, виганяти перед тобою народи ці мало-помалу; не можеш ти знищити їх швидко, щоб [земля не стала пустою і] не примножилися проти тебе польові звірі;","але видасть їх тобі Господь, Бог твій, і приведе їх у велике сум’яття, так що вони загинуть;","і видасть царів їх у руки твої, і ти знищиш ім’я їх з піднебесної: не устоїть ніхто проти тебе, доки не викоріниш їх.","Ідолів богів їх спаліть вогнем; не побажай взяти собі срібла або золота, що на них, щоб це не було для тебе тенетами, тому що це мерзотність для Господа, Бога твого;","і не внось мерзотність у дім твій, щоб не підпасти під закляття, як вона; відвертайся від цього і гребуй цим, бо це закляте."],"x":{"1":"1.23.23|25.105.34|4.31.3:7","2":"3.33.53|1.23.32|1.34.12","4":"1.23.33|1.34.16|5.23.13","5":"1.23.24|3.33.52|10.16.33","6":"4.14.2|4.26.18|53.1.12","8":"4.10.15|31.63.9|53.3.16","9":"4.4.39|4.32.4|63.1.9","10":"1.14.24|44.1.2","12":"1.23.22|2.26.6","14":"1.23.26","15":"1.7.17|1.8.2|1.15.26","16":"1.23.24:33","17":"4.8.17","19":"4.4.34|4.5.15|4.29.3","20":"1.23.28|5.24.12","21":"4.31.6","22":"29.18.15-16","25":"4.12.3|22.12.40|13.15.16","26":"5.6.17|5.7.11"}},{"v":["Усі заповіді, які я заповідаю вам сьогодні, намагайтеся виконувати, щоб ви були живими і розмножилися, і пішли і заволоділи [доброю] землею, яку з клятвою обіцяв Господь [Бог] батькам вашим.","І пам’ятай весь шлях, яким вів тебе Господь, Бог твій, по пустелі, ось уже сорок років, щоб смирити тебе, щоб випробувати тебе і дізнатися, що в серці твоєму, чи будеш зберігати заповіді Його, чи ні;","Він смиряв тебе, морив тебе голодом і годував тебе манною, якої не знав ти і не знали батьки твої, щоб показати тобі, що не єдиним хлібом живе людина, але всяким [словом], яке виходить з вуст Господа, живе людина;","одяг твій не старів на тобі, і нога твоя не пухла, ось уже сорок років.","І знай у серці твоєму, що Господь, Бог твій, учить тебе, як людина учить сина свого.","Отже, зберігай заповіді Господа, Бога твого, ходячи путями Його і бійся Його.","Бо Господь, Бог твій, веде тебе в землю добру, у землю, де потоки вод, джерела й озера виходять з долин і гір,","у землю, [де] пшениця, ячмінь, виноградні лози, смоковниці і гранатові дерева, у землю, де оливкові дерева і мед,","у землю, у якій без убогости будеш їсти хліб твій і ні у чому не будеш мати нестачі, у землю, в якій камені — залізо, і з гір якої будеш висікати мідь.","І коли будеш їсти і насичуватися, тоді благословляй Господа, Бога твого, за добру землю, яку Він дав тобі.","Бережися, щоб ти не забув Господа, Бога твого, не дотримуючи заповідей Його, і законів Його, і постанов Його, які сьогодні заповідаю тобі.","Коли будеш їсти і насичуватися, і побудуєш гарні доми і будеш жити [в них],","і коли буде в тебе багато великої і дрібної худоби, і буде багато срібла і золота, і всього в тебе буде багато, —","то дивися, щоб не стало гордовитим серце твоє і не забув ти Господа, Бога твого, Який вивів тебе з землі Єгипетської, з дому рабства;","Який провів тебе по пустелі великій і страшній, де змії, василіски, скорпіони і місця сухі, на яких немає води; Який виточив для тебе [джерело] води зі скелі гранітної,","насичував тебе в пустелі манною, якої [не знав ти і] не знали батьки твої, щоб смирити тебе і випробувати тебе, щоб з часом зробити тобі добро,","і щоб ти не сказав у серці твоєму: «моя сила і міць руки моєї придбали мені багатство це»,","але щоб пам’ятав Господа, Бога твого, бо Він дає тобі силу здобувати багатство, щоб виконати, як нині, завіт Свій, який Він клятвою утвердив батькам твоїм.","Якщо ж ти забудеш Господа, Бога твого, і підеш услід богів інших, і будеш служити їм і поклонятися їм, то свідчу вам сьогодні [небом і землею], що ви загинете;","як народи, які Господь [Бог] знищує від лиця вашого, так загинете і ви за те, що не послухаєте голосу Господа, Бога вашого."],"x":{"1":"26.3.2|16.7.21","2":"4.29.5|29.3.5","3":"50.4.4|52.4.4","4":"4.29.5|17.9.21","5":"4.1.31|25.88.31|26.3.12","10":"4.6.11-12|62.14.6|71.4.5","14":"4.6.12|4.9.12","15":"1.17.6|3.20.10","16":"1.16.14-15|25.77.24|29.16.20|53.6.31|63.10.3","17":"4.7.17|4.9.4","19":"4.4.26|4.11.28|4.30.18"}},{"v":["Слухай, Ізраїлю: ти тепер ідеш за Йордан, щоб піти оволодіти народами, більшими і сильнішими за тебе, містами великими, з укріпленнями до небес,","народом [великим,] численним і високорослим, синами Енаковими, про яких ти знаєш і чув: «хто устоїть проти синів Енакових?»","Знай же нині, що Господь, Бог твій, іде перед тобою, як вогонь, що поїдає; Він буде знищувати їх і поборювати їх перед тобою, і ти проженеш їх, і погубиш їх скоро, як говорив тобі Господь.","Коли буде виганяти їх Господь, Бог твій, від лиця твого, не говори в серці твоєму, що за праведність мою привів мене Господь оволодіти цією [доброю] землею, і що за нечестя народів цих Господь виганяє їх від лиця твого;","не за праведність твою і не за правоту серця твого йдеш ти успадковувати землю їх, але за нечестя [і беззаконня] народів цих Господь, Бог твій, виганяє їх від лиця твого, і щоб виконати слово, яким клявся Господь батькам твоїм Аврааму, Ісааку та Якову;","тому знай [нині], що не за праведність твою Господь, Бог твій, дає тобі оволодіти цією доброю землею, бо ти народ жорстокосердий.","Пам’ятай, не забудь, скільки ти дратував Господа, Бога твого, у пустелі: від самого того дня, як вийшов ти з землі Єгипетської, і до самого приходу вашого на місце це ви противилися Господу.","І при Хориві ви дратували Господа, і прогнівався на вас Господь, так що хотів знищити вас,","коли я зійшов на гору, щоб прийняти скрижалі кам’яні, скрижалі завіту, який уклав Господь з вами, і пробув на горі сорок днів і сорок ночей, хліба не їв і води не пив,","і дав мені Господь дві скрижалі кам’яні, написані перстом Божим, а на них [написані були] усі слова, які виголосив вам Господь на горі із середовища вогню в день зібрання.","Після закінчення ж сорока днів і сорока ночей дав мені Господь дві скрижалі кам’яні, скрижалі завіту,","і сказав мені Господь: встань, піди скоріше звідси, бо розбестився народ твій, який ти вивів з Єгипту; швидко ухилилися вони від путі, яку Я заповів їм; вони зробили собі відлитого ідола.","І сказав мені Господь: [Я говорив тобі один і другий раз:] бачу Я народ цей, ось він народ жорстокосердий;","не утримуй Мене, і Я знищу їх, і зітру ім’я їх з піднебесної, а від тебе породжу народ, який буде [більшим,] сильнішим і численнішим за них.","Я обернувся і пішов з гори, гора ж горіла вогнем; дві скрижалі завіту були в обох руках моїх;","і бачив я, що ви згрішили проти Господа, Бога вашого, зробили собі відлитого тельця, швидко ухилилися від путі, якої [триматися] заповів вам Господь;","і взяв я обидві скрижалі, і кинув їх з обох рук своїх, і розбив їх перед очима вашими.","І [вдруге] упавши перед Господом, молився я, як раніше, сорок днів і сорок ночей, хліба не їв і води не пив, за всі гріхи ваші, якими ви згрішили, зробивши зло в очах Господа [Бога вашого] і роздратувавши Його;","бо я страшився гніву і лютости, якими Господь прогнівався на вас і хотів погубити вас. І послухав мене Господь і цього разу.","І на Аарона дуже прогнівався Господь і хотів погубити його; але я молився й за Аарона в той час.","Гріх же ваш, який ви зробили, — тельця я взяв, спалив його у вогні, розбив його і всього стер до того, що він став дрібним, як порох, і я кинув порох цей у потік, що тече з гори.","І в Тавері, у Массі й у Киброт-Гаттааві ви роздратували Господа [Бога вашого].","І коли посилав вас Господь з Кадес-Варні, говорячи: підіть, оволодійте землею, яку Я даю вам, — то ви стали проти повеління Господа Бога вашого, і не повірили Йому, і не послухали голосу Його.","Ви були непокірливі Господу з того самого дня, як я став знати вас.","І впавши перед Господом, благав я сорок днів і сорок ночей, в які я молився, бо Господь хотів погубити вас;","і молився я Господу і сказав: Владико Господи, [Царю богів,] не погубляй народу Твого і наділу Твого, який Ти визволив величчю [могутности] Твоєї, який вивів Ти з Єгипту рукою сильною [і силою Твоєю великою];","пом’яни рабів Твоїх, Авраама, Ісаака та Якова, [яким Ти клявся Собою]; не дивися на озлоблення народу цього і на нечестя його і на гріхи його,","щоб [ті, що живуть] у тій землі, звідки Ти вивів нас, не сказали: «Господь не міг ввести їх у землю, яку обіцяв їм, і, ненавидячи їх, вивів Він їх, щоб умертвити їх у пустелі».","А вони Твій народ і Твій наділ, який Ти вивів [із землі Єгипетської] силою Твоєю великою і могутністю Твоєю високою."],"x":{"1":"4.7.1|4.11.23","2":"3.13.23","3":"1.24.17|4.4.24|75.12.29","5":"29.12.3","7":"1.14.11|1.16.2|1.17.2|3.20.4","8":"1.32.10","9":"1.24.18|1.34.28","10":"1.31.18|1.32.16|1.34.29","11":"1.31.18","12":"1.32.7","13":"1.33.3","14":"1.32.10","15":"1.32.15|75.12.18","17":"1.32.19","18":"1.32.31|1.34.28","20":"1.32.21","21":"1.32.20|11.23.12","22":"1.17.7","23":"3.13.3|3.14.2","25":"1.32.11","26":"3.14.13","27":"1.32.13","28":"3.14.16"}},{"v":["У той час сказав мені Господь: витеши собі дві скрижалі кам’яні, подібні до перших, і піднімись до Мене на гору, і зроби собі дерев’яний ковчег;","і Я напишу на скрижалях ті слова, які були на попередніх скрижалях, які ти розбив; і поклади їх у ковчег.","І зробив я ковчег з дерева ситим, і витесав дві кам’яні скрижалі, як попередні, і пішов на гору; і дві ці скрижалі були в руках моїх.","І написав Він на скрижалях, як написано було раніше, ті десять слів, які оголосив вам Господь на горі із середовища вогню в день зібрання, і віддав їх Господь мені.","І повернувся я, і зійшов з гори, і поклав скрижалі в ковчег, який я зробив, щоб вони були там, як повелів мені Господь.","І сини Ізраїлеві рушили з Беероф-Бене-Яакана в Мозер; там помер Аарон і похований там, і став священиком замість нього син його Єлеазар.","Звідти рушили в Гудгод, з Гудгода в Іотвафу, у землю, де потоки вод.","У той час відокремив Господь коліно Левіїне, щоб носити ковчег завіту Господнього, стояти перед Господом, служити Йому [і молитися] і благословляти ім’ям Його, як це триває до цього дня;","тому у левита немає частини і наділу з братами його: Сам Господь є наділом його, як говорив йому Господь, Бог твій.","І пробув я на горі, як і в попередні рази, сорок днів і сорок ночей; і послухав мене Господь і цього разу, [і] не побажав Господь погубити тебе;","і сказав мені Господь: встань, піди в путь перед народом [цим]; нехай вони підуть і оволодіють землею, яку Я клявся батькам їхнім дати їм.","Отже, Ізраїлю, чого вимагає від тебе Господь, Бог твій? Того тільки, щоб ти боявся Господа, Бога твого, ходив усіма путями Його, і любив Його, і служив Господу, Богу твоєму, від усього серця твого і від усієї душі твоєї,","щоб дотримував заповідей Господа [Бога твого] і постанов Його, які сьогодні заповідаю тобі, щоб тобі було добре.","Ось у Господа Бога Твого, небо і небеса небес, земля й усе, що на ній;","але тільки батьків твоїх прийняв Господь і полюбив їх, і обрав вас, сі?м’я їх після них, з усіх народів, як нині бачиш.","Отже, обріжте крайню плоть серця вашого і не будьте надалі жорстокосердими,","бо Господь, Бог ваш, є Бог богів і Владика владик, Бог великий, сильний і страшний, Який не дивиться на особи і не бере дарів,","Який дає суд сироті і вдові, і любить прибулого, і дає йому хліб і одяг.","Любіть і ви прибульця, тому що самі були прибульцями в землі Єгипетській.","Господа, Бога твого, бійся [і] Йому [одному] служи, і до Нього приліпись, і Його ім’ям клянися:","Він хвала твоя і Він Бог твій, Який зробив із тобою ті великі і страшні діла, які бачили очі твої;","у сімдесяти [п’ятьох] душах прийшли батьки твої в Єгипет, а нині Господь Бог твій, зробив тебе численним, як зірки небесні."],"x":{"1":"1.34.1","2":"4.9.10|1.32.19|1.34.4|1.37.1","4":"1.32.16|1.34.28|4.9.10","5":"10.8.9","6":"3.20.29|3.33.31","7":"3.33.32","8":"3.3.12|3.4.25|3.18.5:7","9":"3.18.20|4.18.2|36.44.28","10":"1.32.14","12":"43.6.8|4.6.5|50.22.37|52.10.27","14":"0.14.19|10.8.27|25.23.1","16":"4.30.6|32.4.4","17":"13.19.7|24.34.19|29.6.7|30.35.12|32.32.19|54.10.34|56.1.17|62.2.11|65.2.6|66.6.9|68.3.25","20":"4.6.13|50.4.10|52.4.8","22":"0.46.27"}},{"v":["Отже, люби Господа, Бога твого, і дотримуй, що повелено Ним дотримувати, і постанови Його і закони Його і заповіді Його в усі дні.","І згадайте нині, — бо я говорю не з синами вашими, які не знають і не бачили покарання Господа Бога вашого, — Його велич [і] Його міцну руку і велику силу Його,","знамення Його і діла Його, які Він зробив серед Єгипту з фараоном, царем Єгипетським, і з усією землею його,","і що Він зробив з військом єгипетським, з конями його і колісницями його, яких Він потопив у водах Червоного моря, коли вони гналися за вами, — і погубив їх Господь [Бог] навіть до цього дня;","і що Він робив для вас у пустелі, доки ви не дійшли до місця цього,","і що Він зробив з Дафаном і Авироном, синами Елиава, сина Рувимового, коли земля розверзла вуста свої і серед усього Ізраїля поглинула їх і сімейства їхні, і намети їхні, і все майно їхнє, що було в них;","бо очі ваші бачили усі великі діла Господа, які Він зробив.","Отже, дотримуйте всіх заповідей [Його], які я заповідаю вам сьогодні, щоб ви [були живі,] зміцнилися і пішли й оволоділи землею, в яку ви переходите [за Йордан], щоб оволодіти нею;","і щоб ви жили багато часу на тій землі, яку клявся Господь батькам вашим дати їм і сімені їхньому на землі, в якій тече молоко і мед.","Бо земля, у яку ти йдеш, щоб оволодіти нею, не така, як земля Єгипетська, з якої вийшли ви, де ти, посіявши насіння твоє, поливав [її] за допомогою ніг твоїх, як оливковий сад;","але земля, у яку ви переходите, щоб оволодіти нею, є земля з горами і долинами, і від дощу небесного напоюється водою, —","земля, про яку Господь, Бог твій, піклується: очі Господа, Бога твого, безперестанно на ній, від початку року і до кінця року.","Якщо ви будете слухати заповіді Мої, які заповідаю вам сьогодні, любити Господа, Бога вашого, і служити Йому від усього серця вашого і від усієї душі вашої,","то дам землі вашій дощ у свій час, ранній і пізній; і ти збереш хліб твій і вино твоє і єлей твій;","і дам траву на полі твоєму для худоби твоєї, і будеш їсти і насичуватися.","Бережіться, щоб не спокусилося серце ваше, і ви не ухилилися і не стали служити іншим богам і не поклонилися їм;","і тоді запалає гнів Господа на вас, і закриє Він небо, і не буде дощу, і земля не принесе плодів своїх, і ви швидко загинете на добрій землі, яку Господь дає вам.","Отже, покладіть ці слова Мої в серце ваше й у душу вашу, і нав’яжіть їх як ознаку на руку свою, і нехай будуть вони пов’язкою над очима вашими;","і навчайте їх синів своїх, говорячи про них, коли ти сидиш у домі твоєму, і коли йдеш дорогою, і коли лягаєш, і коли встаєш;","і напиши їх на одвірках дому твого і на воротах твоїх,","щоб стільки ж багато було днів ваших і днів дітей ваших на тій землі, яку Господь клявся дати батькам вашим, скільки днів небо буде над землею.","Бо якщо ви будете дотримувати всіх заповідей цих, які заповідаю вам виконувати, будете любити Господа, Бога вашого, ходити всіма путями Його і приліплюватися до Нього,","то прожене Господь усі народи ці від лиця вашого, і ви оволодієте народами, які більші і сильніші за вас;","усяке місце, на яке ступить нога ваша, буде ваше; від пустелі й Ливану, від ріки, ріки Євфрату, навіть до моря західного будуть межі ваші;","ніхто не устоїть проти вас: Господь, Бог ваш, наведе страх і трепет перед вами на всяку землю, на яку ви ступите, як Він говорив вам.","Ось, я пропоную вам сьогодні благословення і прокляття:","благословення, якщо послухаєте заповідей Господа, Бога вашого, які я заповідаю вам сьогодні,","а прокляття, якщо не послухаєте заповідей Господа, Бога вашого, і ухилитеся від путі, яку заповідаю вам сьогодні, і підете вслід богів інших, яких ви не знаєте.","Коли введе тебе Господь, Бог твій, у ту землю, у яку ти йдеш, щоб оволодіти нею, тоді проголоси благословення на горі Гаризим, а прокляття на горі Гевал:","ось вони за Йорданом, по дорозі до заходу сонця, у землі хананеїв, що живуть на рівнині, навпроти Галгала, біля діброви Море?.","Бо ви переходите Йордан, щоб оволодіти землею, яку Господь, Бог ваш, дає вам [у наділ назавжди], й оволодієте нею і будете жити на ній.","Отже, намагайтеся дотримувати всіх постанов і законів [Його], які пропоную я вам сьогодні."],"x":{"1":"4.12.1","4":"1.14.25|1.15.1","6":"3.16.30|25.105.17","9":"4.4.40|4.5.33","10":"10.21.2","11":"25.64.10|25.103.13","12":"25.64.12","13":"4.28.1-2","14":"2.26.4|32.5.24|38.6.3","16":"1.23.24","17":"2.26.19-20|4.4.26","18":"4.6.6:8|26.6.21|1.13.9","19":"4.4.9|4.6.7","20":"4.6.9","21":"25.88.30","22":"4.6.5","23":"4.7.1","24":"5.1.3","25":"1.23.27","26":"4.28.2:15|4.30.1:15","28":"4.8.19|4.27.15|4.28.15","29":"4.27.12|5.8.33-34|6.9.7","30":"0.12.6|0.18.1"}},{"v":["Ось постанови і закони, які ви повинні намагатися виконувати в землі, яку Господь, Бог батьків твоїх, дає тобі у володіння, в усі дні, в які ви будете жити на тій землі.","Знищіть усі місця, де народи, якими ви оволодієте, служили богам своїм, на високих горах і на пагорбах, і під усяким гіллястим деревом;","і зруйнуйте жертовники їх, і розтрощіть стовпи їх, і спаліть вогнем діброви їх, і розбийте статуї богів їх, і знищіть ім’я їх на місці тому.","Не те повинні ви робити для Господа, Бога вашого;","але до місця, яке обере Господь, Бог ваш, із усіх колін ваших щоб перебувати імені Його, там, звертайтеся і туди приходьте,","і туди приносьте всепалення ваші, і жертви ваші, і десятини ваші, і возношення рук ваших, і обітниці ваші, і добровільні приношення ваші, [і мирні жертви ваші,] і первістків великої худоби вашої і дрібної худоби вашої;","і їжте там перед Господом, Богом вашим, і веселіться ви і родини ваші за все, що робилося руками вашими, чим благословив тебе Господь, Бог твій.","Там ви не повинні робити всього, як ми тепер тут робимо, кожен, що йому здається правильним;","бо ви нині ще не вступили в місце спокою і в наділ, який Господь, Бог твій, дає тобі.","Але коли перейдете Йордан і оселитеся на землі, яку Господь, Бог ваш, дає вам у наділ, і коли Він заспокоїть вас від усіх ворогів ваших, які оточують вас, і будете жити безпечно,","тоді, яке місце обере Господь, Бог ваш, щоб перебувати імені Його там, туди приносьте все, що я заповідаю вам [сьогодні]: всепалення ваші і жертви ваші, десятини ваші і возношення рук ваших, і все, обране за обітницями вашими, що ви обіцяли Господу [Богу вашому];","і веселіться перед Господом, Богом вашим, ви і сини ваші, і дочки ваші, і раби ваші, і рабині ваші, і левит, який посеред осель ваших, бо немає йому частини і наділу з вами.","Бережися приносити всепалення твої на всякому місці, яке ти побачиш;","але на тому тільки місці, яке обере Господь [Бог твій] в одному з колін твоїх, принось всепалення твої і роби усе, що заповідаю тобі [сьогодні].","Втім, коли тільки побажає душа твоя, можеш заколоти і їсти, з благословення Господа, Бога твого, м’ясо, яке Він дав тобі, у всіх оселях твоїх: нечистий і чистий можуть їсти це, як сарну і як оленя;","тільки крови не їжте: на землю виливайте її, як воду.","Не можна тобі їсти в оселях твоїх десятини хліба твого, і вина твого, і єлею твого, і первістків великої худоби твоєї і дрібної худоби твоєї, і всіх обітниць твоїх, які ти обіцяв, і добровільних приношень твоїх, і возношення рук твоїх;","але їж це [тільки] перед Господом, Богом твоїм, на тім місці, яке обере Господь, Бог твій, — ти і син твій, і дочка твоя, і раб твій, і рабиня твоя, і левит, [і прибулець,] який в оселях твоїх, і веселися перед Господом, Богом твоїм, за все, що робилося руками твоїми.","Дивися, не залишай левита в усі дні, [в які будеш жити] на землі твоїй.","Коли розширить Господь, Бог твій, межі твої, як Він говорив тобі, і ти скажеш: «поїм я м’яса», тому що душа твоя побажає їсти м’яса, — тоді, за бажанням душі твоєї, їж м’ясо,","Якщо далеко буде від тебе те місце, яке обере Господь, Бог твій, щоб перебувати імені Його там, то заколюй з великої і дрібної худоби твоєї, яку дав тобі Господь [Бог твій], як я повелів тобі, і їж в оселях твоїх, за бажанням душі твоєї;","але їж їх так, як їдять сарну й оленя; нечистий як і чистий [у тебе] можуть їсти це;","тільки суворо стеж, щоб не їсти крови, тому що кров є душа: не їж душі разом з м’ясом;","не їж її: виливай її на землю, як воду;","не їж її, щоб добре було тобі і дітям твоїм після тебе [повік], якщо будеш робити [добре і] справедливе перед очима Господа [Бога твого].","Тільки святині твої, які будуть у тебе, і обітниці твої принось, і приходь на те місце, яке обере Господь [Бог твій, щоб прикликане було там ім’я Його];","і звершуй всепалення твої, м’ясо і кров, на жертовнику Господа, Бога твого; але кров інших жертв твоїх повинна бути вилитою біля жертовника Господа, Бога твого, а м’ясо їж.","Слухай і виконуй усі слова ці, які заповідаю тобі, щоб добре було тобі і дітям твоїм після тебе повік, якщо будеш робити добре й угодне перед очима Господа, Бога твого.","Коли Господь, Бог твій, знищить від лиця твого народи, до яких ти йдеш, щоб взяти їх у володіння, і ти, взявши їх, оселишся в землі їх;","тоді стережися, щоб ти не потрапив у тенета, наслідуючи їх, після знищення їх від лиця твого, і не шукав богів їх, говорячи: «як служили народи ці богам своїм, так буду і я робити»;","не роби так Господу, Богу твоєму, бо все, чим гребує Господь, що ненавидить Він, вони роблять богам своїм: вони і синів своїх і дочок своїх спалюють на вогні богам своїм.","Усе, що я заповідаю вам, намагайтеся виконати; не додавай до того і не віднімай від того."],"x":{"1":"4.11.1","2":"1.34.13","5":"1.20.24","6":"38.3.4","7":"4.14.23","9":"75.4.8","10":"10.8.56","11":"10.8.29|11.21.4|13.33.4|32.32.34","12":"3.18.20:24|4.10.9","13":"38.8.11","15":"4.14.5","16":"0.9.4","17":"2.27.30","18":"4.14.23","19":"4.14.27","20":"0.28.14|4.19.8","22":"4.15.22","23":"2.4.1-2|26.30.6","30":"4.18.9|5.23.7|32.10.2","31":"2.18.21|11.16.3","32":"4.4.1-2|26.30.6"}},{"v":["Якщо постане серед тебе пророк, або сновидець, і покаже тобі знамення або чудо,","і збудеться те знамення або чудо, про яке він говорив тобі, і скаже притому: «ходімо услід богів інших, яких ти не знаєш, і будемо служити їм», —","то не слухай слів пророка цього, або сновидця цього; тому що через це спокушає вас Господь, Бог ваш, щоб довідатися, чи любите ви Господа, Бога вашого, від усього серця вашого і від усієї душі вашої;","За Господом, Богом вашим, ходіть і Його бійтеся, заповідей Його дотримуйте і голосу Його слухайте, і Йому служіть, і до Нього приліплюйтеся;","а пророка того або сновидця того слід віддати на смерть за те, що він умовляв вас відступити від Господа, Бога вашого, Який вивів вас із землі Єгипетської і визволив тебе з дому рабства, бажаючи звести тебе з путі, якою заповів тобі йти Господь, Бог твій; і так знищ зло із середовища свого.","Якщо буде умовляти тебе таємно брат твій, [син батька твого або] син матері твоєї, або син твій, або дочка твоя, або дружина на лоні твоєму, або друг твій, який для тебе, як душа твоя, говорячи: «ходімо і будемо служити богам іншим, яких не знав ти і батьки твої»,","богам тих народів, які навколо тебе, близьких до тебе або віддалених від тебе, від одного краю землі до іншого, —","то не погоджуйся з ним і не слухай його; і нехай не пощадить його око твоє, не шкодуй його і не прикривай його,","але убий його; твоя рука раніше за всіх повинна бути на ньому, щоб убити його, а потім руки всього народу;","побий його камінням до смерти, бо він мав намір відвернути тебе від Господа, Бога твого, Який вивів тебе з землі Єгипетської, з дому рабства;","весь Ізраїль почує це й убоїться, і не стануть надалі робити серед тебе такого зла.","Якщо почуєш про яке-небудь з міст твоїх, які Господь, Бог твій, дає тобі для поселення,","що з’явилися в ньому нечестиві люди із середовища твого і спокусили жителів міста їхнього, говорячи: «ходімо і будемо служити богам іншим, яких ви не знали», —","то ти розшукай, досліди і добре розпитай; і якщо це дійсно правда, що сталася мерзота ця серед тебе,","урази жителів того міста вістрям меча, піддай прокляттю його й усе, що в ньому, і худобу його урази вістрям меча;","всю ж здобич його збери на середину площі його і спали вогнем місто і всю здобич його у всепалення Господу, Богу твоєму, і нехай буде він вічно в руїнах, не слід ніколи знову будувати його;","ніщо з заклятого нехай не прилипне до руки твоєї, щоб відвернув Господь лють гніву Свого, і дав тобі милість і помилував тебе, і розмножив тебе, [як Він говорив тобі,] коли клявся батькам твоїм,","якщо будеш слухати голосу Господа, Бога твого, дотримуючи всіх заповідей Його, які нині заповідаю тобі, роблячи [добре і] угодне перед очима Господа, Бога твого."],"x":{"1":"3.12.6|50.24.24|10.13.3","2":"32.14.14","3":"50.7.15|6.2.22|50.6.13","4":"4.8.6|4.10.20|43.6.8","5":"4.18.20|32.14.15|10.18.40|63.5.13","6":"4.17.2|4.22.19|50.10.37","8":"4.19.13","9":"4.17.7","11":"4.17.13|4.19.20","13":"9.20.1|10.21.10|64.2.15","15":"5.22.12|4.2.34","17":"4.7.25-26|5.6.17|5.7.13"}},{"v":["Ви сини Господа Бога вашого; не робіть нарізів на тілі вашому і не вистригайте волосся над очима вашими за померлим;","бо ти народ святий у Господа Бога твого, і тебе обрав Господь, щоб ти був власним Його народом із усіх народів, які на землі.","Не їж ніякої мерзоти.","Ось худоба, яку вам можна їсти: воли, вівці, кози,","олень і сарна, і буйвіл, і лань, і зубр, і антилопа, і жирафа.","Усяка худоба, у якої роздвоєні копита і на обох копитах глибокий розріз, і яка худоба жує жуйку, ту їжте;","тільки цих не їжте з тих, що жують жуйку і мають роздвоєні копита з глибоким розрізом: верблюда, зайця і тушканчика, тому що, хоча вони жують жуйку, але копита в них не роздвоєні: нечисті вони для вас;","і свині, тому що копита в неї роздвоєні, але не жує жуйки: нечиста вона для вас; не їжте м’яса їх, і до трупів їх не доторкайтеся.","Із усіх тварин, що у воді, їжте усіх, у яких є пір’я і луска;","а всіх тих, у яких немає пір’я і луски, не їжте: нечисте це для вас.","Всякого птаха чистого їжте;","але цих не слід вам їсти з них: орла, грифа і морського орла,","і шуліки, і сокола, і кречета з породою їх,","і всякого ворона з породою його,","і страуса, і сови, і чайки, і яструба з породою його,","і пугача, й ібіса, і лебедя,","і пелікана, і сипа, і рибалки,","і чаплі, і зуя з породою його, й удода, і нетопиря.","Усі крилаті плазуни нечисті для вас, не їжте [їх].","Усякого птаха чистого їжте.","Не їжте ніякої мертвечини; іноземцеві, який трапиться в оселях твоїх, віддай її, він нехай їсть її, або продай йому, тому що ти народ святий у Господа Бога твого. Не вари козеняти в молоці матері його.","Відділяй десятину від усього врожаю насіння твого, що надходить з поля [твого] щорічно,","і їж перед Господом, Богом твоїм, на тім місці, яке обере Він, щоб перебувати імені Його там; [принось] десятину хліба твого, вина твого і єлею твого, і первістків великої худоби твоєї і дрібної худоби твоєї, щоб ти навчився боятися Господа, Бога твого, в усі дні.","Якщо ж довгою буде для тебе дорога, так що ти не можеш нести цього, тому що далеко від тебе те місце, яке обере Господь, Бог твій, щоб покласти там ім’я Своє, і Господь, Бог твій, благословив тебе,","то обміняй це на срібло і візьми срібло в руку твою і приходь на місце, яке обере Господь, Бог твій;","і купуй на срібло це все, чого бажає душа твоя: волів, овець, вино, сикер і все, чого зажадає від тебе душа твоя; і їж там перед Господом, Богом твоїм, і веселися ти і родина твоя.","І левита, який в оселях твоїх, не залиш, бо немає йому частини і наділу з тобою.","Після того ж, як мине три роки, відділяй усі десятини здобутків твоїх у той рік і поклади [це] в оселях твоїх;","і нехай прийде левит, бо йому немає частини і наділу з тобою, і прибулець, і сирота, і вдова, які знаходяться в оселях твоїх, і нехай їдять і насичуються, щоб благословив тебе Господь, Бог твій, у всякому ділі рук твоїх, яке ти будеш робити."],"x":{"1":"2.19.27-28|10.18.28","2":"4.7.6|4.26.18","3":"54.10.14","4":"2.11.2","5":"4.12.15","7":"2.11.4","8":"31.65.4","9":"2.11.9","12":"2.11.13","21":"1.23.19|1.34.26","22":"2.27.30|3.18.21","23":"4.12.7|50.21.12","25":"50.21.12","26":"2.10.9|4.27.7","27":"3.18.20:24","28":"2.27.30","29":"26.10.24-25|64.9.6"}},{"v":["У сьомий рік роби прощення.","Прощення ж полягає в тому, щоб усякий позикодавець, який дав у борг ближньому своєму, простив борг і не стягував із ближнього свого або з брата свого, бо проголошено прощення заради Господа [Бога твого];","з іноземця стягуй, а що буде твоє у брата твого, прости.","Хіба тільки не буде в тебе жебрака: бо благословить тебе Господь на тій землі, яку Господь, Бог твій, дає тобі в наділ, щоб ти взяв її у спадщину,","якщо тільки будеш слухати голосу Господа, Бога твого, і намагатися виконувати всі заповіді ці, які я сьогодні заповідаю тобі;","бо Господь, Бог твій, благословить тебе, як Він говорив тобі, і ти будеш давати в борг багатьом народам, а сам не будеш брати в борг; і володарювати будеш над багатьма народами, а вони над тобою не будуть панувати.","Якщо ж буде в тебе убогий хто-небудь із братів твоїх, в одній із осель твоїх, на землі твоїй, яку Господь, Бог твій, дає тобі, то не озлоби серця твого і не стисни руки твоєї перед убогим братом твоїм,","але відкрий йому руку твою і дай йому в борг, дивлячись за його нестатком, у чому він має потребу;","бережися, щоб не ввійшла в серце твоє беззаконна думка: «наближається сьомий рік, рік прощення», і щоб від того око твоє не зробилося немилостивим до убогого брата твого, і ти не відмовив йому; бо він заволає проти тебе до Господа, і буде на тобі [великий] гріх;","дай йому [і в борг дай йому, скільки він просить і скільки йому потрібно], і коли будеш давати йому, не повинно сумувати серце твоє, бо за те благословить тебе Господь, Бог твій, у всіх ділах твоїх і в усьому, що буде робитися твоїми руками;","бо жебраки завжди будуть серед землі [твоєї]; тому я і повеліваю тобі: відкривай руку твою братові твоєму, бідному твоєму й убогому твоєму на землі твоїй.","Якщо продасться тобі брат твій, єврей, або єврейка, то шість років повинен він бути рабом твоїм, а в сьомий рік відпусти його від себе на волю;","коли ж будеш відпускати його від себе на волю, не відпусти його з порожніми руками,","але дай йому від стад твоїх, від току твого і від точила твого: дай йому, чим благословив тебе Господь, Бог твій:","пам’ятай, що [і] ти був рабом у землі Єгипетській, і визволив тебе Господь, Бог твій, тому я сьогодні і заповідаю тобі це.","Якщо ж він скаже тобі: «не піду я від тебе, тому що я люблю тебе і дім твій», тому що добре йому в тебе,","то візьми шило і проколи вухо його до дверей; і буде він рабом твоїм навіки. Так учини і з рабою твоєю.","Не вважай цього для себе тяжким, що ти повинен відпустити його від себе на волю, тому що він за шість років заробив тобі вдвічі проти платні найманця; і благословить тебе Господь, Бог твій, в усьому, що будеш робити.","Усе первородне чоловічої статі, що народиться від великої худоби твоєї і від дрібної худоби твоєї, присвячуй Господу, Богу твоєму: не працюй на первородному волі твоєму і не стрижи первородного з дрібної худоби твоєї;","перед Господом, Богом твоїм, щорічно з’їдай це ти і родина твоя, на місці, яке обере Господь [Бог твій];","якщо ж буде на ньому вада, кульгавість або сліпота [або] інша яка-небудь вада, то не принось його в жертву Господу, Богу твоєму,","але в оселях твоїх їж його; нечистий, як і чистий, [можуть їсти,] як сарну і як оленя;","тільки крови його не їжте: на землю виливай її, як воду."],"x":{"1":"1.21.2|2.25.4|32.34.14","4":"30.4.1","5":"4.28.1-2","6":"4.28.11-12","7":"1.22.25|2.25.35|50.5.42","8":"50.5.42","9":"64.6.15","10":"50.5.42|52.6.30","11":"50.26.11","12":"1.21.2|32.34.14","13":"0.21.14|13.28.15","16":"1.21.5-6","19":"1.13.2|1.22.30|3.3.13","20":"4.12.11","21":"2.22.20|30.35.11","22":"4.12.15","23":"2.3.17|2.17.10|4.12.16:23"}},{"v":["Додержуй місяця Авива, і звершуй Пасху Господу, Богу твоєму, тому що в місяці Авиві вивів тебе Господь, Бог твій, з Єгипту вночі.","І заколюй Пасху Господу, Богу твоєму, з дрібної і великої худоби на місці, яке обере Господь, щоб перебувало там ім’я Його.","Не їж з нею квасного; сім днів їж з нею опрісноки, хліби бідування, бо ти з поспіхом вийшов із землі Єгипетської, щоб ти пам’ятав день виходу свого з землі Єгипетської в усі дні життя твого;","не повинне знаходитися у тебе ніщо квасне в усьому наділі твоєму впродовж семи днів, і з м’яса, яке ти приніс у жертву ввечері в перший день, ніщо не повинне залишатися до ранку.","Не можеш ти заколоти Пасху в якій-небудь з осель твоїх, які Господь, Бог твій, дасть тобі;","але тільки на тім місці, яке обере Господь, Бог твій, щоб перебувало там ім’я Його, заколюй Пасху увечері при заході сонця, у той самий час, в який ти вийшов з Єгипту;","і спечи і з’їж на тім місці, яке обере Господь, Бог твій, а на другий день можеш повернутися і ввійти в намети твої.","Шість днів їж прісні хліби, а в сьомий день віддання свята Господу, Богу твоєму; не займайся працею.","Сім седмиць відрахуй собі; починай рахувати сім седмиць з того часу, як з’явиться серп на жнивах;","тоді звершуй свято седмиць Господу, Богу твоєму, за ревністю руки твоєї, скільки ти даси, дивлячись на те, чим благословить тебе Господь, Бог твій;","і веселися перед Господом, Богом твоїм, ти, і син твій, і дочка твоя, і раб твій, і рабиня твоя, і левит, що в оселях твоїх, і прибулець, і сирота, і вдова, яка серед тебе, на місці, яке обере Господь, Бог твій, щоб перебувало там ім’я Його;","пам’ятай, що ти був рабом у Єгипті, і дотримуй і виконуй постанови ці.","Свято кущів звершуй у себе сім днів, коли збереш з току твого і з точила твого;","і веселися у свято твоє ти, і син твій, і дочка твоя, і раб твій, і рабиня твоя, і левит, і прибулець, і сирота, і вдова, які в оселях твоїх;","сім днів святкуй Господу, Богу твоєму, на місці, яке обере Господь, Бог твій, [щоб прикликане було там ім’я Його]; бо благословить тебе Господь, Бог твій, у всіх здобутках твоїх, і в усякому ділі рук твоїх, і ти будеш тільки веселитися.","Тричі на рік уся чоловіча стать повинна з’являтися перед лице Господа, Бога твого, на місце, яке обере Він: у свято опрісноків, у свято седмиць і у свято кущів; і ніхто не повинен бути перед лицем Господа з порожніми руками,","але кожний з даром у руці своїй, дивлячись за благословенням Господа, Бога твого, яке Він дав тобі.","В усіх оселях твоїх, які Господь, Бог твій, дасть тобі, постав собі суддів і наглядачів за колінами твоїми, щоб вони судили народ судом праведним;","не викривляй закону, не дивися на особи і не бери дарунків, тому що дарунки засліплюють очі мудрих і перекручують справу правих;","правди, правди шукай, щоб ти був живим і оволодів землею, яку Господь, Бог твій, дає тобі.","Не сади собі діброву з яких-небудь дерев біля жертовника Господа, Бога твого, який ти зробиш собі,","і не став собі стовпа, що ненавидить Господь Бог твій."],"x":{"1":"1.12.18|2.23.5|3.9.2","2":"1.12.3|3.28.19|4.12.5","3":"1.12.14:39","4":"1.12.10:20|13.35.1:18","6":"51.14.13-14|52.2.41-42|1.12.6","7":"1.12.9|13.35.13","8":"1.12.15|2.23.8","9":"2.23.15|3.28.26|52.6.1","10":"1.23.6|1.34.22|4.26.2","11":"17.8.10","13":"1.23.16|2.23.34|10.8.2","14":"17.8.10","16":"1.23.17|1.34.23|30.35.4","17":"18.4.8","18":"13.19.5|29.6.5|25.81.3","19":"1.23.8|2.19.15|4.1.17|26.24.23|30.20.29|53.7.24|55.2.1","22":"2.26.1"}},{"v":["Не принось у жертву Господу, Богу твоєму, вола, або вівці, на якій буде вада, або що-небудь недобре, бо це мерзота для Господа, Бога твого.","Якщо знайдеться серед тебе в якій-небудь з осель твоїх, які Господь, Бог твій, дає тобі, чоловік або жінка, хто вчинить зло перед очима Господа, Бога твого, переступивши завіт Його,","і піде і буде служити іншим богам, і поклониться їм, або сонцю, або місяцю, або усьому воїнству небесному, чого я не повелів,","і тобі сповіщено буде, і ти почуєш, то ти добре розвідай; і якщо це дійсно правда, якщо вчинена мерзота ця в Ізраїлі,","то виведи чоловіка того, або жінку ту, які вчинили зло це, до воріт твоїх і побий їх камінням до смерти.","За словами двох свідків, або трьох свідків, повинен померти засуджений на смерть: не слід віддавати на смерть за словом одного свідка;","рука свідків повинна бути на ньому раніше за всіх, щоб убити його, потім рука всього народу; і так знищи зло із середовища свого.","Якщо з якої справи важко буде для тебе розсудити між кров’ю і кров’ю, між судом і судом, між побоями і побоями, і будуть незгодні думки біля воріт твоїх, то встань і піди на місце, яке обере Господь, Бог твій, [щоб прикликане було там ім’я Його,]","і прийди до священиків левитів і до судді, який буде в ті дні, і запитай їх, і вони скажуть тобі, як розсудити;","і вчини за словом, яке вони скажуть тобі, на тім місці, яке обере Господь [Бог твій, щоб прикликане було там ім’я Його,] і постарайся виконати все, чого вони навчать тебе;","за законом, якого навчать вони тебе, і за визначенням, яке вони скажуть тобі, вчини, і не ухиляйся ні праворуч, ні ліворуч від того, що вони скажуть тобі.","А хто вчинить так зухвало, що не послухає священика, який стоїть там на служінні перед Господом, Богом твоїм, або судді, [який буде в ті дні], той повинен умерти, — і так знищи зло від Ізраїля;","і весь народ почує й убоїться, і не будуть надалі чинити зухвало.","Коли ти прийдеш у землю, яку Господь, Бог твій, дає тобі, й оволодієш нею, і оселишся на ній, і скажеш: «поставлю я над собою царя, подібно до інших народів, що навколо мене»,","то постав над собою царя, якого обере Господь, Бог твій; із середовища братів твоїх постав над собою царя; не можеш поставити над собою [царем] іноземця, який не брат тобі.","Тільки щоб він не примножував собі коней і не повертав народ в Єгипет для примноження собі коней, бо Господь сказав вам: «не повертайтеся більше дорогою цією»;","і щоб не примножував собі дружин, щоб не розбестилося серце його, і щоб срібла і золота не множив собі надмірно.","Але коли він сяде на престолі царства свого, повинен переписати для себе список закону цього з книги, що знаходиться у священиків левитів,","і нехай він буде в нього, і нехай він читає його в усі дні життя свого, щоб навчався боятися Господа, Бога свого, і намагався виконувати всі слова закону цього і постанови ці;","щоб не гордувало серце його перед братами його, і щоб не ухилявся він від закону ні праворуч, ні ліворуч, щоб довгі дні перебував на царстві своєму він і сини його серед Ізраїля."],"x":{"1":"2.22.20|4.15.21|49.1.8:13","2":"4.13.6-7","3":"4.4.19|32.8.2","6":"4.19.15|50.18.16|53.8.17|64.13.1|75.10.28","7":"4.13.9|63.5.13","8":"13.19.10","9":"13.19.8:11|49.2.7|50.23.3","11":"4.5.32|4.28.14","12":"10.18.26","13":"4.13.11|4.19.20|62.13.14","14":"8.8.5|38.13.10|54.13.21","16":"8.10.25|10.4.26","17":"9.5.13","18":"10.1.13","19":"25.118.12:24|50.5.19","20":"25.130.2|5.1.7-8"}},{"v":["Священикам левитам, усьому коліну Левіїному, не буде частини і наділу з Ізраїлем: вони повинні годуватися жертвами Господа і Його частиною;","наділу ж не буде йому між братами його: Сам Господь наділ його, як говорив Він йому.","Ось, що повинно бути покладено священикам від народу, від тих, що приносять у жертву волів або овець: слід віддавати священикові плече, щелепи і шлунок;","також початки від хліба твого, вина твого і єлею твого, і початки від вовни овець твоїх віддавай йому,","бо його обрав Господь Бог твій із усіх колін твоїх, щоб він стояв [перед Господом, Богом твоїм], служив [і благословляв] в ім’я Господа, сам і сини його в усі дні.","І якщо левит прийде з однієї з осель твоїх, з усієї землі [синів] Ізраїлевих, де він жив, і прийде за бажанням душі своєї на місце, яке обере Господь,","і буде служити в ім’я Господа Бога свого, як і всі брати його левити, які стоять там перед Господом, —","то нехай вони користуються одинаковою частиною, зверх отриманого від продажу батьківського майна.","Коли ти ввійдеш у землю, яку дає тобі Господь Бог твій, тоді не навчися робити мерзоти, які чинили народи ці:","не повинен знаходитись у тебе той, хто проводить сина свого або дочку свою через вогонь, віщун, знахар, ворожка, чаклун,","чорнокнижник, що викликає духів, чарівник і той, хто викликає померлих;","бо мерзенний перед Господом усякий, хто робить це, і за ці ось мерзоти Господь Бог твій виганяє їх від лиця твого;","будь непорочним перед Господом Богом твоїм;","бо народи ці, яких ти виганяєш, слухають ворожбитів і віщунів, а тобі не те дав Господь Бог твій.","Пророка із середовища твого, із братів твоїх, як мене, воздвигне тобі Господь Бог твій, — Його слухайте, —","оскільки ти просив у Господа Бога твого при Хориві в день зібрання, говорячи: нехай не почую надалі голосу Господа Бога мого і вогню цього великого нехай не побачу більше, щоб мені не вмерти.","І сказав мені Господь: добре те, що вони говорили [тобі];","Я воздвигну їм Пророка із середовища братів їхніх, такого як ти, і вкладу слова Мої у вуста Його, і Він буде говорити їм усе, що Я повелю Йому;","а хто не послухає слів Моїх, які [Пророк той] буде говорити Моїм ім’ям, з того Я стягну;","але пророка, який насмілиться говорити Моїм ім’ям те, чого Я не повелів йому говорити, і який буде говорити ім’ям богів інших, такого пророка віддайте на смерть.","І якщо скажеш у серці твоєму: «як ми впізнаємо слово, яке не Господь говорив?»","Якщо пророк скаже ім’ям Господа, але слово те не збудеться і не сповниться, то не Господь говорив це слово, але говорив це пророк із зухвалости своєї, — не бійся його."],"x":{"1":"3.18.20|4.10.9|63.9.13","4":"17.10.37|36.44.30","9":"2.18.26|4.12.30","10":"2.20.27|8.28.7","15":"54.3.22|54.7.37","16":"1.20.19|75.12.18-20","18":"53.1.45|53.6.14","19":"11.2.24|53.12.48","20":"4.13.5|32.14.14","21":"32.23.31","22":"32.28.9"}},{"v":["Коли Господь Бог твій знищить народи, землю яких дає тобі Господь Бог твій і ти вступиш у спадщину після них, і оселишся в містах їх і домах їх,","тоді відокрем собі три міста серед землі твоєї, яку Господь Бог твій дає тобі у володіння;","влаштуй собі дорогу і розділи на три частини всю землю твою, яку Господь Бог твій дає тобі в наділ; вони будуть служити притулком всякому вбивці.","І ось який убивця може тікати туди і залишитися живим: хто уб’є ближнього свого без наміру, не бувши ворогом йому вчора і третього дня;","хто піде з ближнім своїм у ліс рубати дрова, і розмахнеться рука його із сокирою, щоб зрубати дерево, і зіскочить залізо із сокирища і попаде у ближнього, і він помре, — такий нехай утече в одне із міст тих, щоб залишитися живим,","щоб месник за кров у гарячковості серця свого не погнався за вбивцею і не наздогнав його, якщо далекою буде дорога, і не вбив його, в той час як він не підлягає засудженню на смерть, бо не був ворогом йому вчора і третього дня;","тому я і дав тобі повеління, говорячи: відокрем собі три міста.","Коли ж Господь Бог твій розширить межі твої, як Він клявся батькам твоїм, і дасть тобі всю землю, яку Він обіцяв дати батькам твоїм,","якщо ти будеш намагатися виконувати всі ці заповіді, які я заповідаю тобі сьогодні, любити Господа Бога твого і ходити путями Його в усі дні, — тоді до цих трьох міст додай ще три міста,","щоб не проливалася кров невинного серед землі твоєї, яку Господь Бог твій дає тобі в наділ, і щоб не було на тобі [провини] крови.","Але якщо хто [в тебе] буде ворогом ближньому своєму і буде підстерігати його, і повстане на нього й уб’є його до смерти, і втече в одне з міст тих,","то старійшини міста його повинні послати, щоб узяти його звідти і віддати його в руки месника за кров, щоб він помер;","нехай не щадить його око твоє; змий з Ізраїля кров невинного, і буде тобі добре.","Не порушуй межі ближнього твого, яку поклали предки в наділі твоєму, що дістався тобі на землі, яку Господь Бог твій дає тобі у володіння.","Недостатньо одного свідка проти кого-небудь у якій-небудь провині й у якому-небудь злочині й у якому-небудь гріху, яким він згрішить: за словами двох свідків, або за словами трьох свідків відбудеться [усяка] справа.","Якщо виступить проти кого свідок несправедливий, звинувачуючи його в злочині,","то нехай стануть обидва ці чоловіки, у яких тяжба, перед Господом, перед священиками і перед суддями, які будуть у ті дні;","судді повинні добре дослідити, і якщо свідок той свідок неправдивий, неправдиво доніс на брата свого,","то зробіть йому те, що він замислив зробити братові своєму; і так знищи зло із середовища свого;","й інші почують, і убояться, і не стануть надалі чинити таке зло серед тебе;","нехай не пощадить [його] око твоє: душу за душу, око за око, зуб за зуб, руку за руку, ногу за ногу. [Яку хто зробить шкоду ближньому своєму, так слід відплатити йому.]"],"x":{"2":"1.21.13|3.35.10-11|4.4.41|5.20.2","4":"3.35.22","6":"3.35.12","7":"5.20.7","8":"0.28.14|4.12.20","9":"5.20.8","11":"3.35.20","12":"3.35.19:21|9.14.7","13":"4.13.8|10.2.31","14":"4.27.17|26.22.28|38.5.10","15":"3.35.30|4.17.6|50.18.16|53.8.17|64.13.1|75.10.28","17":"4.17.9","19":"26.19.5|63.5.13","20":"4.13.11|4.17.13","21":"1.21.24|2.24.20|50.5.38"}},{"v":["Коли ти вийдеш на війну проти ворога твого і побачиш коней і колісниці [і] народу більше, ніж у тебе, то не бійся їх, бо з тобою Господь Бог твій, Який вивів тебе з землі Єгипетської.","Коли ж приступаєте до бою, тоді нехай підійде священик, і говорить народу,","і скаже йому: слухай, Ізраїлю! ви сьогодні вступаєте в бій з ворогами вашими, нехай не ослабне серце ваше, не бійтеся, не бентежтеся і не жахайтеся їх,","бо Господь Бог ваш іде з вами, щоб воювати за вас з ворогами вашими [і] спасти вас.","Наглядачі ж нехай оголосять народу, говорячи: хто побудував новий дім і не оновив його, той нехай іде і повернеться в дім свій, щоб не помер у бою, й інший не оновив його;","і хто насадив виноградник і не користувався ним, той нехай йде і повернеться в дім свій, щоб не вмер в бою, й інший не скористався їм;","і хто заручився з жінкою і не взяв її, той нехай іде і повернеться в дім свій, щоб не вмер у бою, й інший не взяв її.","І ще оголосять наглядачі народу, і скажуть: хто боязкий і легкодухий, той нехай іде і повернеться в дім свій, щоб він не зробив боязкими серця братів його, як його серце.","Коли наглядачі скажуть усе це народу, тоді слід поставити військових начальників вождями народу.","Коли підійдеш до міста, щоб завоювати його, запропонуй йому мир;","якщо воно погодиться на мир з тобою і відчинить тобі ворота, то весь народ, що знаходиться в ньому, буде платити тобі данину і служити тобі;","якщо ж воно не погодиться на мир з тобою і буде вести з тобою війну, то обложи його,","і коли Господь Бог твій віддасть його в руки твої, врази у ньому всю чоловічу стать вістрям меча;","тільки жінок і дітей і худобу й усе, що в місті, всю здобич його візьми собі і користуйся здобиччю ворогів твоїх, яких віддав тобі Господь Бог твій;","так чини з усіма містами, які від тебе дуже далеко, які не з числа міст народів цих.","А в містах цих народів, які Господь Бог твій дає тобі у володіння, не залишай у живих жодної душі,","але піддай їх прокляттю: хеттеїв і аморреїв, і хананеїв, і ферезеїв, і евеїв, і ієвусеїв, [і гергесеїв,] як повелів тобі Господь Бог твій,","щоб вони не навчили вас чинити такі самі мерзоти, які вони робили для богів своїх, і щоб ви не грішили перед Господом Богом вашим.","Якщо довгий час будеш тримати в облозі [яке-небудь] місто, щоб завоювати його і взяти його, то не пошкоджуй дерев його, від яких можна годуватися, і не спустошуй околиць, тому що дерево на полі не людина, щоб могло піти від тебе в укріплення;","тільки ті дерева, про які ти знаєш, що вони нічого не приносять для їжі, можеш псувати і рубати, і будувати укріплення проти міста, що веде з тобою війну, доки не підкориш його."],"x":{"2":"3.31.6","5":"21.3.56","6":"2.19.23|4.28.30","7":"4.24.5","8":"6.7.3","10":"3.21.21","13":"3.31.7|10.11.16","14":"3.31.27","17":"4.7.1-2|5.6.17","19":"6.2.17","20":"32.6.6"}},{"v":["Якщо в землі, яку Господь Бог твій дає тобі у володіння, знайдений буде вбитий, що лежить на полі, і невідомо, хто вбив його,","то нехай вийдуть старійшини твої і судді твої і виміряють відстань до міст, які навколо вбитого;","і старійшини міста того, яке буде найближчим до вбитого, нехай візьмуть телицю, на якій не працювали, [і] яка не носила ярма,","і нехай старійшини того міста відведуть цю телицу в дику долину, що не орана і не засіяна, і заколють там телицю в долині;","і прийдуть священики, сини Левіїні [тому що їх обрав Господь Бог твій служити Йому і благословляти ім’ям Господа, і за словом їхнім слід вирішити всяку спірну справу і всяку заподіяну шкоду,]","й усі старійшини міста того, найближчі до вбитого, нехай обмиють руки свої над [головою] телиці, зарізаної в долині,","і оголосять і скажуть: руки наші не пролили крови цієї, і очі наші не бачили;","очисти народ Твій, Ізраїля, який Ти, Господи, визволив [із землі Єгипетської], і не постав народу Твоєму, Ізраїлю, невинної крови. І вони очистяться від крови.","Так повинен ти змивати у себе кров невинного, якщо хочеш робити [добре і] справедливе перед очима Господа [Бога твого].","Коли вийдеш на війну проти ворогів твоїх, і Господь Бог твій віддасть їх у руки твої, і візьмеш їх у полон,","і побачиш між полоненими жінку, красиву на вигляд, і полюбиш її, і захочеш узяти її собі за дружину,","то приведи її в дім свій, і нехай вона обстриже голову свою й обріже нігті свої,","і зніме з себе полоненичий одяг свій, і живе в домі твоєму, й оплакує батька свого і матір свою впродовж місяця; і після того ти можеш увійти до неї і стати її чоловіком, і вона буде твоєю дружиною;","якщо ж вона потім не сподобається тобі, то відпусти її, куди вона захоче, але не продавай її за срібло і не повертай її в рабство, тому що ти смирив її.","Якщо в кого будуть дві дружини — одна улюблена, а інша нелюба, і як улюблена, так і нелюба народять йому синів, і первістком буде син нелюбої, —","то, при розділі синам своїм майна свого, він не може синові дружини улюбленої дати першість перед первородним сином нелюбої;","але первістком повинен визнати сина нелюбої [і] дати йому подвійну частину з усього, що в нього знайдеться, тому що він є початок сили його; йому належить право первородства.","Якщо в кого буде син буйний і непокірливий, який не підкорюється голосу батька свого і голосу матері своєї, і вони карали його, але він не слухав їх, —","то батько його і матір його нехай візьмуть його і приведуть його до старійшин міста свого і до воріт свого місцеперебування","і скажуть старійшинам міста свого: «цей син наш буйний і непокірливий, не слухає слів наших, марнотратник і п’яниця»;","тоді всі жителі міста його нехай поб’ють його камінням до смерти; і так знищи зло із середовища свого, і всі ізраїльтяни почують і убояться.","Якщо в кому знайдеться злочин, гідний смерти, і він буде умертвлений, і ти повісиш його на дереві,","то тіло його не повинно ночувати на дереві, але поховай його в той самий день, тому що проклятий перед Богом [усякий] повішений [на дереві], і не оскверняй землі твоєї, яку Господь Бог твій дає тобі в наділ."],"x":{"5":"4.10.8|4.17.8-9","6":"25.25.6|50.27.24","11":"1.34.16|4.7.3","14":"49.2.16|50.19.8|4.24.1","15":"0.29.30|8.1.5-6","17":"0.49.3|11.2.9","18":"4.13.6:8","21":"4.13.11|4.17.13|4.19.19-20|63.5.13","23":"65.3.13"}},{"v":["Коли побачиш вола брата твого або вівцю його заблукалих, не залишай їх, але поверни їх братові твоєму;","якщо ж не близько буде від тебе брат твій, або ти не знаєш його, то забери їх у дім свій, і нехай вони будуть у тебе, доки брат твій не буде шукати їх, і тоді поверни йому їх;","так чини і з ослом його, так чини з одягом його, так чини з усякою загубленою річчю брата твого, яка буде ним загублена і яку ти знайдеш; не можна тобі ухилятися від цього.","Коли побачиш осла брата твого або вола його, що впали на дорозі, не залишай їх, але підніми їх з ним разом.","На жінці не повинно бути чоловічого одягу, і чоловік не повинен вдягатися в жіноче вбрання, бо мерзенний перед Господом Богом твоїм усякий, що робить це.","Якщо трапиться тобі на дорозі пташине гніздо на якому-небудь дереві або на землі, з пташенятами або яйцями, і мати сидить на пташенятах або на яйцях, то не бери матері разом з дітьми:","матір пусти, а дітей візьми собі, щоб тобі було добре, і щоб продовжилися дні твої.","Якщо будеш будувати новий дім, то зроби поручні біля покрівлі твоєї, щоб не навести тобі крови на дім твій, коли хто-небудь упаде з нього.","Не засівай виноградника свого двома родами насіння, щоб не зробити тобі заклятим збору насіння, яке ти посієш разом із плодами виноградника [свого].","Не ори на волі й ослі разом.","Не вдягай одягу, зробленого з різних речовин, з вовни і льону разом.","Зроби собі китиці на чотирьох кутах покривала твого, яким ти покриваєшся.","Якщо хто візьме дружину, і ввійде до неї, і зненавидить її,","і буде зводити на неї порочні справи, і пустить про неї недобру чутку, і скаже: «я взяв цю дружину, і ввійшов до неї, і не знайшов у неї дівоцтва»,","то батько дівчини і матір її нехай візьмуть і винесуть ознаки дівоцтва дівчини до старійшин міста, до воріт;","і батько дівчини скаже старійшинам: дочку мою я віддав за дружину цьому чоловіку, і [нині] він зненавидів її,","і ось, він зводить [на неї] порочні діла, говорячи: «я не знайшов у дочки твоєї дівоцтва»; але ось ознаки дівоцтва дочки моєї. І розстелять одяг перед старійшинами міста.","Тоді старійшини того міста нехай візьмуть чоловіка і покарають його,","і накладуть на нього сто сиклів срібла пені і віддадуть батькові дівчини за те, що він пустив недобрі чутки про дівчину ізраїльську; вона ж нехай залишиться його дружиною, і він не може розлучитися з нею усе життя своє.","Якщо ж сказане буде правдою, і не знайдеться дівоцтва у дівчини,","то дівчину нехай приведуть до дверей дому батька її, і жителі міста її поб’ють її камінням до смерти, бо вона зробила соромітну справу серед Ізраїля, блудодіючи у домі батька свого; і так знищи зло із середовища свого.","Якщо буде знайдений хтось, що лежить з жінкою заміжньою, то слід віддати на смерть обох: і чоловіка, що лежав із жінкою, і жінку; і так знищи зло в Ізраїлі.","Якщо буде молода дівчина заручена з чоловіком, і хто-небудь зустрінеться з нею в місті і ляже з нею,","то обох їх приведіть до воріт того міста, і побийте їх камінням до смерти: дівчину за те, що вона не кричала в місті, а чоловіка за те, що він осквернив дружину ближнього свого; і так знищи зло із середовища свого.","Якщо ж хто в полі зустрінеться з дівчиною зарученою і, схопивши її, ляже з нею, то слід віддати на смерть тільки чоловіка, що лежав з нею,","а дівчині нічого не роби; на дівчині немає злочину смертного: бо це те саме, як якби хто повстав на ближнього свого й убив його;","бо він зустрівся з нею в полі, і хоча дівчина заручена кричала, але нікому було врятувати її.","Якщо хто-небудь зустрінеться з дівчиною незарученою, і схопить її і ляже з нею, і застануть їх,","то той, що лежав з нею, повинен дати батькові дівчини п’ятдесят [сиклів] срібла, а вона нехай буде його дружиною, тому що він знечестив її; все життя своє він не може розлучитися з нею.","Ніхто не повинен брати дружини батька свого і відкривати край одягу батька свого."],"x":{"1":"1.23.4","4":"50.12.11|52.14.5","6":"26.12.10","8":"6.16.27","9":"2.19.19","11":"2.19.19","12":"3.15.38|50.23.5","21":"0.34.7|5.7.15|63.5.13","22":"2.20.10|53.8.4-5","24":"63.5.13","26":"4.21.22","28":"1.22.16","30":"0.35.22|2.18.8|36.22.10"}},{"v":["У кого роздавлені ятра або відрізаний дітородний член, той не може ввійти в громаду Господню.","Син блудниці не може ввійти в громаду Господню, і десяте покоління його не може ввійти в громаду Господню.","Аммонитянин і моавитянин не може ввійти в громаду Господню, і десяте покоління їхнє не може ввійти в громаду Господню повіки,","тому що вони не зустріли вас із хлібом і водою на шляху, коли ви йшли з Єгипту, і тому що вони найняли проти тебе Валаама, сина Веорового, з Пефора Месопотамського, щоб проклясти тебе;","але Господь, Бог твій, не захотів слухати Валаама і обернув Господь Бог твій прокляття його на благословення тобі, бо Господь Бог твій любить тебе.","Не бажай їм миру і благополуччя в усі дні твої, повіки.","Не гребуй ідумеянином, бо він брат твій; не гребуй єгиптянином, бо ти був прибульцем у землі його;","діти, які в них народяться, у третьому поколінні можуть увійти в громаду Господню.","Коли підеш у похід проти ворогів твоїх, бережися всього злого.","Якщо в тебе буде хто нечистий від того, що трапилося [з ним] уночі, то він повинен вийти геть зі стану і не входити в стан,","а коли настане вечір, повинен омити [тіло своє] водою, і після заходу сонця може ввійти у стан.","У тебе повинно бути місце поза станом, куди ти міг би виходити;","крім зброї твоєї, повинна бути у тебе лопатка; і коли будеш сідати поза станом, викопай нею [яму] і знову зарий [нею] випорожнення твоє;","тому що Господь Бог твій ходить серед стану твого, щоб визволяти тебе і віддавати ворогів твоїх [у руки твої], а тому стан твій повинен бути святий, щоб Він не побачив у тебе чого соромітного і не відступив від тебе.","Не видавай раба господареві його, коли він прибіжить до тебе від господаря свого;","нехай він у тебе живе, серед вас [нехай він живе] на місці, яке він обере в якій-небудь з осель твоїх, де йому сподобається; не пригноблюй його.","Не повинно бути блудниці серед дочок Ізраїлевих і не повинно бути блудника серед синів Ізраїлевих.","Не внось платні блудниці і ціни пса в дім Господа Бога твого ні за якою обітницею, тому що те й інше є мерзота перед Господом Богом твоїм.","Не віддавай у ріст братові твоєму ні срібла, ні хліба, ні чого-небудь іншого, що можна віддавати в ріст;","іноземцеві віддавай у ріст, а братові твоєму не віддавай у ріст, щоб Господь Бог твій благословив тебе в усьому, що робиться руками твоїми, на землі, в яку ти йдеш, щоб оволодіти нею.","Якщо даси обітницю Господу Богу твоєму, негайно виконай її, бо Господь Бог твій стягне її з тебе, і на тобі буде гріх;","якщо ж ти не дав обітниці, то не буде на тобі гріха.","Що вийшло з уст твоїх, дотримуй і виконуй так, як обіцяв ти Господу Богу твоєму добровільне приношення, про яке сказав ти вустами своїми.","Коли ввійдеш у виноградник ближнього твого, можеш їсти ягоди досита, скільки хоче душа твоя, а в посудину твою не клади.","Коли прийдеш на жниво ближнього твого, зривай колосся руками твоїми, але серпа не занось на жниво ближнього твого."],"x":{"2":"6.11.1","3":"17.13.1","4":"3.22.5","5":"3.22.12","7":"0.25.25|3.20.14","10":"2.15.16","14":"2.26.12","16":"1.22.21","17":"3.25.8:11|10.3.16","19":"25.14.5","20":"4.15.3","21":"3.30.3|27.5.3","25":"50.12.1|51.2.23|52.6.1"}},{"v":["Якщо хто візьме дружину і стане її чоловіком, і вона не знайде благовоління в очах його, тому що він знаходить у ній що-небудь огидне, і напише їй розвідний лист, і дасть їй у руки, і відпустить її з дому свого,","і вона вийде з дому його, піде, і вийде за іншого чоловіка,","але і цей останній чоловік зненавидить її і напише їй розвідний лист, і дасть їй у руки, і відпустить її з дому свого, або помре цей останній чоловік її, який взяв її собі за дружину, —","то не може перший її чоловік, який відпустив її, знову взяти її собі за дружину після того, як вона осквернена, тому що це є мерзота перед Господом [Богом твоїм], і не ганьби землі, яку Господь Бог твій дає тобі в наділ.","Якщо хто взяв дружину недавно, то нехай не йде на війну, і нічого не слід покладати на нього; нехай він залишається вільний у домі своєму впродовж одного року і звеселяє дружину свою, яку взяв.","Ніхто не повинен брати в заставу верхнього і нижнього жорна, бо такий бере у заставу душу.","Якщо знайдуть кого, що він украв кого-небудь із братів своїх, із синів Ізраїлевих, і поневолив його, і продав його, то такого злодія слід віддати на смерть; і так знищи зло із середовища свого.","Дивись, у хворобі прокази ретельно дотримуй і виконуй весь [закон], якого навчать вас священики левити; ретельно виконуйте, що я повелів їм;","пам’ятай, що Господь Бог твій зробив з Маріам на шляху, коли ви йшли з Єгипту.","Якщо ти ближньому твоєму даси що-небудь у борг, то не ходи до нього в дім, щоб взяти в нього заставу,","постій на вулиці, а той, якому ти дав у борг, винесе тобі заставу свою на вулицю;","якщо ж він буде людиною бідною, то ти не лягай спати, маючи [у себе] заставу його:","поверни йому заставу до заходу сонця, щоб він ліг спати в одязі своєму і благословив тебе, — і поставиться тобі це в праведність перед Господом Богом твоїм.","Не кривдь наймита, бідного й убогого, із братів твоїх або з прибульців твоїх, які на землі твоїй, у оселях твоїх;","у той самий день віддай платню його, щоб сонце не зайшло раніше того, бо він бідний, і чекає на неї душа його; щоб він не заволав на тебе до Господа, і не було на тобі гріха.","Батьки не повинні бути карані смертю за дітей, і діти не повинні бути карані смертю за батьків; кожен повинен бути караним смертю за свій злочин.","Не суди несправедливо прибульця, сироту [і вдову], і у вдови не бери одяг у заставу;","пам’ятай, що і ти був рабом у Єгипті, і Господь [Бог твій] звільнив тебе звідти: тому я і повеліваю тобі робити це.","Коли будеш жати на полі твоєму, і забудеш сніп на полі, то не повертайся взяти його; нехай він залишається прибульцеві, [убогому,] сироті і вдові, щоб Господь Бог твій благословив тебе в усіх справах рук твоїх.","Коли будеш оббивати маслину твою, то не переглядай за собою гілок: нехай залишається прибульцеві, сироті і вдові. [І пам’ятай, що ти був рабом у землі Єгипетській: тому я і повеліваю тобі робити це.]","Коли будеш знімати плоди у винограднику твоєму, не збирай залишків за собою: нехай залишаються прибульцеві, сироті і вдові;","і пам’ятай, що ти був рабом у землі Єгипетській: тому я і повеліваю тобі робити це."],"x":{"1":"50.5.31|50.19.7-8|51.10.4|52.16.18|63.7.10","4":"32.3.1","5":"4.20.7","7":"1.21.16|71.1.10|63.5.13","8":"2.13.8|2.14.3","9":"3.12.10","12":"40.2.8","13":"1.22.26|36.33.15","14":"2.19.13|18.4.14|30.34.22","16":"11.14.6|13.25.4|36.18.20","17":"1.22.21|2.19.33|25.81.3","19":"2.23.22"}},{"v":["Якщо буде тяжба між людьми, то нехай приведуть їх на суд і розсудять їх, правого нехай виправдають, а винного засудять;","і якщо винний буде заслуговувати на побої, то суддя нехай накаже покласти його і бити при собі, дивлячись за провиною його, за рахунком;","сорок ударів можна дати йому, але не більше, щоб від багатьох ударів брат твій не був спотворений перед очима твоїми.","Не закривай рота волові, коли він молотить.","Якщо брати живуть разом і один з них помре, не маючи в себе сина, то дружина померлого не повинна виходити на сторону за чоловіка чужого, але дівер її повинен увійти до неї і взяти її собі за дружину, і жити з нею, —","і первісток, якого вона народить, залишиться з ім’ям брата його померлого, щоб ім’я його не стерлося в Ізраїлі.","Якщо ж він не захоче взяти невістку свою, то невістка його піде до воріт, до старійшин, і скаже: «дівер мій відмовляється відновити ім’я брата свого в Ізраїлі, не хоче одружитися зі мною»;","тоді старійшини міста його повинні покликати його й умовляти його, і якщо він стане і скаже: «не хочу взяти її»,","тоді невістка його нехай підійде до нього на очах старійшин, і зніме чобіт його з ноги його, і плюне в лице його, і скаже: «так чинять з людиною, яка не творить дому братові своєму [в Ізраїля]»;","і наречуть йому ім’я в Ізраїлі: дім роззутого.","Коли б’ються між собою чоловіки, і дружина одного [з них] підійде, щоб відняти чоловіка свого з рук того, хто б’є його, і, простягнувши руку свою, схопить його за срамний член,","то відсічи руку її: нехай не пощадить [її] око твоє.","У торбі твоїй не повинно бути подвійних гир, великих і менших;","у домі твоєму не повинно бути подвійної ефи, великої і меншої;","гиря в тебе повинна бути точна і правильна, і ефа в тебе повинна бути точна і правильна, щоб продовжилися дні твої на землі, яку Господь Бог твій дає тобі [в наділ];","бо мерзенний перед Господом Богом твоїм усякий, хто робить неправду.","Пам’ятай, як чинив з тобою Амалик на путі, коли ви вийшли з Єгипту:","як він зустрів тебе на путі, і побив позаду тебе всіх ослаблих, коли ти втомився і знесилився, і не побоявся він Бога;","отже, коли Господь Бог твій заспокоїть тебе від усіх ворогів твоїх з усіх боків, на землі, яку Господь Бог твій дає тобі в наділ, щоб оволодіти нею, згладь пам’ять Амалика з піднебесної; не забудь."],"x":{"1":"26.17.15","3":"64.11.24","4":"63.9.9|71.5.18|30.7.24","5":"50.22.24|51.12.19|52.20.28","7":"7.4.4","9":"7.4.7","12":"4.13.8","13":"2.19.36|26.20.10:23|36.45.10","15":"2.19.36|4.4.40","16":"4.17.1","17":"1.17.8","18":"5.10.19","19":"8.15.3|1.17.14"}},{"v":["Коли ти прийдеш у землю, яку Господь Бог твій дає тобі в наділ, і оволодієш нею, і оселишся на ній,","то візьми початки усіх плодів землі, які ти одержиш від землі твоєї, яку Господь Бог твій дає тобі, і поклади в кошик, і піди на те місце, яке Господь Бог твій обере, щоб перебувало там ім’я Його;","і прийди до священика, який буде в ті дні, і скажи йому: сьогодні сповідаю перед Господом Богом твоїм, що я ввійшов у ту землю, яку Господь клявся батькам нашим дати нам.","Священик візьме кошик з руки твоєї і поставить його перед жертовником Господа Бога твого.","Ти ж відповідай і скажи перед Господом Богом твоїм: батько мій був подорожнім арамеянином, і пішов у Єгипет і оселився там з деякими людьми, і народився там від нього народ великий, сильний і численний;","але єгиптяни зле поводилися з нами, і пригноблювали нас, і накладали на нас тяжкі роботи;","і заволали ми до Господа Бога батьків наших, і почув Господь крик наш і побачив біду нашу, працю нашу і пригноблення наше;","і вивів нас Господь з Єгипту [Сам кріпкістю Своєю великою і] рукою сильною і могутністю, великим жахом, знаменнями і чудесами,","і привів нас на місце це, і дав нам землю цю, землю, в якій тече молоко і мед;","отже, ось, я приніс початки плодів від землі, яку Ти, Господи, дав мені, [від землі, де тече молоко і мед]. І постав це перед Господом Богом твоїм, і поклонися перед Господом Богом твоїм,","і веселися за всі блага, що Господь Бог твій дав тобі і дому твоєму, ти і левит і прибулець, що буде в тебе.","Коли ти відокремиш усі десятини здобутків [землі] твоєї на третій рік, рік десятин, і віддаси левитові, прибульцеві, сироті і вдові, щоб вони їли в оселях твоїх і насичувалися,","тоді скажи перед Господом Богом твоїм: я відібрав від дому [мого] святиню і віддав її левитові, прибульцеві, сироті і вдові, за всіма повеліннями Твоїми, які Ти заповів мені: я не переступив заповідей Твоїх і не забув;","я не їв від неї в печалі моїй, і не відокремлював її в нечистоті, і не давав з неї для мертвого; я корився гласу Господа Бога мого, виконав усе, що Ти заповів мені;","споглянь від святої оселі Твоєї, з небес, і благослови народ Твій, Ізраїля, і землю, яку Ти дав нам — тому що Ти клявся батькам нашим [дати нам] землю, в якій тече молоко і мед.","У день цей Господь Бог твій заповідає тобі виконувати [усі] постанови ці і закони: дотримуй і виконуй їх від усього серця твого і від усієї душі твоєї.","Господу сказав ти нині, що Він буде твоїм Богом, і що ти будеш ходити путями Його і зберігати постанови Його і заповіді Його і закони Його, і слухати голос Його;","і Господь обіцяв тобі нині, що ти будеш власним Його народом, як Він говорив тобі, якщо ти будеш зберігати всі заповіді Його,","і що Він поставить тебе вище за всі народи, які Він створив, у честі, славі і красі, і що ти будеш святим народом у Господа Бога твого, як Він говорив."],"x":{"2":"1.23.19|1.34.26","5":"0.46.5|1.12.37","6":"1.1.11","7":"1.2.23-24","8":"1.12.51","9":"1.3.8|1.13.5","10":"4.14.22","11":"4.16.14","12":"2.27.30","13":"4.14.27","14":"32.16.7|36.24.17","15":"31.63.15","16":"4.6.5","17":"4.5.31","18":"4.7.6|4.14.2","19":"4.4.7|4.28.1|32.13.11"}},{"v":["І заповів Мойсей і старійшини [синів] Ізраїлевих народу, говорячи: виконуйте всі заповіді, які заповідаю вам нині.","І коли перейдете за Йордан, у землю, яку Господь Бог твій дає тобі, тоді постав собі великі камені й обмаж їх вапном;","і напиши на [каменях] цих усі слова закону цього, коли перейдеш [Йордан], щоб вступити в землю, яку Господь Бог твій дає тобі, в землю, де тече молоко і мед, як говорив тобі Господь Бог батьків твоїх.","Коли перейдете Йордан, поставте камені ті, як я повеліваю вам сьогодні, на горі Гевал, і обмажте їх вапном;","і влаштуй там жертовник Господу Богу твоєму, жертовник з каменів, не піднімаючи на них заліза;","з каменів цільних влаштуй жертовник Господа Бога твого, і принось на ньому всепалення Господу Богу твоєму,","і принось жертви мирні, і їж [і насичуйся] там, і веселися перед Господом Богом твоїм;","і напиши на каменях [цих] усі слова закону цього дуже виразно.","І сказав Мойсей і священики левити всьому Ізраїлю, говорячи: будь уважним і слухай, Ізраїлю: у день цей ти став народом Господа Бога твого;","отже, слухай голос Господа Бога твого і виконуй [усі] заповіді Його і постанови Його, які заповідаю тобі сьогодні.","І заповів Мойсей народу в день той, говорячи:","ці повинні стати на горі Гаризим, щоб благословляти народ, коли перейдете Йордан: Симеон, Левій, Іуда, Іссахар, Йосиф і Веніамін;","а ці повинні стати на горі Гевал, щоб вимовляти прокляття: Рувим, Гад, Асир, Завулон, Дан і Неффалим.","Левити виголосять і скажуть усім ізраїльтянам гучним голосом:","проклятий, хто зробить виліпленого або відлитого ідола, мерзоту перед Господом, творіння рук митця, і поставить його в таємному місці! Весь народ виголосить і скаже: амінь.","Проклятий той, хто лихословить батька свого або матір свою! І весь народ скаже: амінь.","Проклятий той, хто порушує межі ближнього свого! І весь народ скаже: амінь.","Проклятий той, хто сліпого збиває з дороги! І весь народ скаже: амінь.","Проклятий той, хто перекручено судить прибульця, сироту і вдову! І весь народ скаже: амінь.","Проклятий той, хто ляже з дружиною батька свого, бо він відкрив край одягу батька свого! І весь народ скаже: амінь.","Проклятий той, хто ляже з якою-небудь худобою! І весь народ скаже: амінь.","Проклятий той, хто ляже із сестрою своєю, з дочкою батька свого, або дочкою матері своєї! І весь народ скаже: амінь.","Проклятий той, хто ляже з тещею своєю! І весь народ скаже: амінь. [Проклятий той, хто ляже із сестрою дружини своєї! І весь народ скаже: амінь.]","Проклятий той, хто таємно убиває ближнього свого! І весь народ скаже: амінь.","Проклятий той, хто бере підкуп, щоб убити душу і пролити кров невинну! І весь народ скаже: амінь.","Проклята [усяка людина], що не виконає [усіх] слів закону цього і не буде чинити за ними! І весь народ скаже: амінь."],"x":{"2":"5.3.17","3":"5.8.32|1.3.8|4.26.9","5":"1.20.25|5.8.31|35.2.16","7":"4.14.26","9":"4.26.18","10":"4.26.17|4.28.1","12":"4.11.29","15":"37.9.11","16":"1.21.17|2.20.9|26.20.20","17":"4.19.14","19":"1.22.21|2.19.33-34|32.5.28","20":"2.18.8|2.20.11|36.22.10","21":"1.22.19|2.18.23","22":"2.18.9","23":"0.38.18|2.18.15","24":"0.9.6|1.21.12|2.24.17","25":"1.23.8","26":"65.3.10"}},{"v":["Якщо ти, коли перейдете [за Йордан у землю, яку Господь Бог ваш дає вам], будеш слухати голос Господа Бога твого, старанно виконувати всі заповіді Його, які заповідаю тобі сьогодні, то Господь Бог твій поставить тебе вище за всі народи землі;","і прийдуть на тебе усі благословення ці і сповняться на тобі, якщо будеш слухати голос Господа, Бога твого.","Благословенний ти в місті і благословенний на полі.","Благословенний плід утроби твоєї, і плід землі твоєї, і плід худоби твоєї, і плід твоїх волів, і плід овець твоїх.","Благословенні житниці твої і комори твої.","Благословенний ти при вході твоєму і благословенний ти при виході твоєму.","Уразить перед тобою Господь ворогів твоїх, які повстають на тебе; однією дорогою вони виступлять проти тебе, а сімома дорогами побіжать від тебе.","Пошле Господь тобі благословення в житницях твоїх і в усякій справі рук твоїх; і благословить тебе на землі, яку Господь Бог твій дає тобі.","Поставить тебе Господь [Бог твій] народом святим Своїм, як Він клявся тобі [і батькам твоїм], якщо ти будеш дотримувати заповідей Господа Бога твого і будеш ходити путями Його;","і побачать усі народи землі, що ім’я Господа [Бога твого] нарікається на тобі, й убояться тебе.","І дасть тобі Господь [Бог твій] достаток у всіх благах, у плоді утроби твоєї, і в плоді худоби твоєї, і в плоді полів твоїх на землі, яку Господь клявся батькам твоїм дати тобі.","Відкриє тобі Господь добру скарбницю Свою, небо, щоб воно давало дощ землі твоїй у свій час, і щоб благословляти всі діла рук твоїх: і будеш давати в борг багатьом народам, а сам не будеш брати в борг [і будеш панувати над багатьма народами, а вони над тобою не будуть панувати].","Зробить тебе Господь [Бог твій] головою, а не хвостом, і будеш тільки на висоті, а не будеш внизу, якщо будеш підкорюватися заповідям Господа Бога твого, які заповідаю тобі сьогодні зберігати і виконувати,","і не відступиш від усіх слів, які заповідую вам сьогодні, ні праворуч, ні ліворуч, щоб піти вслід іншим богам і служити їм.","Якщо ж не будеш слухати голосу Господа Бога твого і не будеш намагатися виконувати всі заповіді Його і постанови Його, які я заповідую тобі сьогодні, то прийдуть на тебе всі прокляття ці й осягнуть тебе.","Проклятим ти [будеш] у місті і проклятим ти [будеш] на полі.","Проклятими [будуть] житниці твої і комори твої.","Проклятим [буде] плід утроби твоєї і плід землі твоєї, плід твоїх волів і плід овець твоїх.","Проклятим ти [будеш] при вході твоєму і проклятим при виході твоєму.","Пошле Господь на тебе прокляття, сум’яття і біди в усякій справі рук твоїх, яку станеш ти робити, доки не будеш знищений, — і ти швидко загинеш за злі справи твої, за те, що ти залишив Мене.","Пошле Господь на тебе моровицю, доки не знищить Він тебе з землі, в яку ти йдеш, щоб володіти нею.","Вразить тебе Господь чахлістю, гарячкою, лихоманкою, запаленням, засухою, палючим вітром та іржею, і вони будуть переслідувати тебе, доки не загинеш.","І небеса твої, які над головою твоєю, зробляться міддю, і земля під тобою залізом;","замість дощу Господь дасть землі твоїй пил, і порох з неба буде падати, падати на тебе, [доки не погубить тебе і] доки не будеш знищений.","Віддасть тебе Господь на поразку ворогам твоїм; однією дорогою виступиш проти них, а сімома дорогами побіжиш від них; і будеш розсіяний по всіх царствах землі.","І будуть трупи твої їжею всім птахам небесним і звірам, і не буде того, хто відганятиме їх.","Уразить тебе Господь проказою єгипетською, почечуєм, коростою і сверблячкою, від яких ти не зможеш зцілитися;","вразить тебе Господь божевіллям, сліпотою й оціпенінням серця.","І ти будеш навпомацки ходити опівдні, як сліпий навпомацки ходить у пітьмі, і не будеш мати успіху в путях твоїх, і будуть тіснити і кривдити тебе кожного дня, і ніхто не захистить тебе.","З жінкою заручишся, й інший буде спати з нею; дім побудуєш, і не будеш жити в ньому; виноградник насадиш, і не будеш користуватися ним.","Вола твого заколють на очах твоїх, і не будеш їсти його; осла твого поведуть від тебе і не повернуть тобі; вівці твої віддані будуть ворогам твоїм, і ніхто не захистить тебе.","Сини твої і дочки твої будуть віддані іншому народу; очі твої будуть бачити і кожного дня вболівати за них, і не буде сили в руках твоїх.","Плоди землі твоєї і всю працю твою буде їсти народ, якого ти не знав; і ти будеш тільки пригнобленим і мучимим в усі дні.","І збожеволієш від того, що будуть бачити очі твої.","Вразить тебе Господь злою проказою на колінах і гомілках, від якої ти не зможеш зцілитися, від підошви ноги твоєї до самого тімені [голови] твоєї.","Відведе Господь тебе і царя твого, якого ти поставиш над собою, до народу, якого не знав ні ти, ні батьки твої, і там будеш служити іншим богам, дерев’яним і кам’яним;","і будеш жахом, притчею і посміховищем у всіх народах, до яких відведе тебе Господь [Бог].","Багато насіння винесеш у поле, а збереш мало, тому що поїсть його сарана.","Виноградники будеш садити й обробляти, а вина не будеш пити, і не збереш плодів [їх], тому що поїсть їх черва.","Маслини будуть у тебе у всіх межах твоїх, але єлеєм не помажешся, тому що обсипеться маслина твоя.","Синів і дочок народиш, але їх не буде в тебе, тому що підуть у полон.","Усі дерева твої і плоди землі твоєї погубить іржа.","Прибулець, який серед тебе, буде підніматися над тобою вище і вище, а ти опускатися будеш нижче і нижче;","він буде давати тобі в борг, а ти не будеш давати йому в борг; він буде головою, а ти будеш хвостом.","І прийдуть на тебе всі прокляття ці, і будуть переслідувати тебе й осягнуть тебе, доки не будеш знищений, за те, що ти не слухав голосу Господа Бога твого і не дотримував заповідей Його і постанов Його, які Він заповів тобі:","вони будуть знаменням і вказівкою на тобі і на сімені твоєму повік.","За те, що ти не служив Господу Богу твоєму з веселістю і радістю серця, при достатку всього,","будеш служити ворогові твоєму, якого пошле на тебе Господь [Бог твій], у голоді, і спразі, і наготі й у всякій нестачі; він покладе на шию твою залізне ярмо, так що змучить тебе.","Пошле на тебе Господь народ здалеку, від краю землі: як орел налетить народ, мови якого ти не розумієш,","народ нахабний, який не шанує старця і не пощадить юнака;","і буде він їсти плід і худоби твоєї і плід землі твоєї, доки не розорить тебе, так що не залишить тобі ні хліба, ні вина, ні єлею, ні плоду волів твоїх, ні плоду овець твоїх, доки не погубить тебе;","і буде тіснити тебе в усіх оселях твоїх, доки у всій землі твоїй не зруйнує високих і міцних стін твоїх, на які ти надієшся; і буде тіснити тебе у всіх оселях твоїх, по всій землі твоїй, яку Господь Бог твій дав тобі.","І ти будеш їсти плід утроби твоєї, плоть синів твоїх і дочок твоїх, яких Господь Бог твій дав тобі, в облозі й в утиску, в якому стисне тебе ворог твій.","Чоловік, зніжений, який жив між вами у великій розкоші, безжалісним оком буде дивитися на брата свого, на дружину надра свого і на інших дітей своїх, які залишаться в нього,","і не дасть жодному з них плоті дітей своїх, яких він буде їсти, тому що в нього не залишиться нічого в облозі й в утиску, в якому стисне тебе ворог твій у всіх оселях твоїх.","[Жінка] яка жила в тебе в достатку і розкошах, яка ніколи ноги своєї не ставила на землю через розкіш і зніженість, буде безжалісним оком дивитися на чоловіка надра свого і на сина свого і на дочку свою","і не дасть їм посліду, що виходить з-поміж ніг її, і дітей, яких вона родить; тому що вона, при нестачі в усьому, таємно буде їсти їх, в облозі й утиску, в якому стисне тебе ворог твій у оселях твоїх.","Якщо не будеш намагатися виконувати всі слова закону цього, написані в книзі цій, і не будеш боятися цього славного і страшного імені Господа Бога твого,","то Господь уразить тебе і потомство твоє надзвичайними виразками, виразками великими і постійними, і хворобами злими і постійними;","і наведе на тебе всі [злі] виразки єгипетські, яких ти боявся, і вони прилипнуть до тебе;","і всяку хворобу і всяку виразку, не написану [і всяку написану] у книзі закону цього, Господь наведе на тебе, доки не будеш знищений;","і залишиться вас небагато, тоді як безліччю ви подібні були до зірок небесних, тому що ти не слухав голосу Господа Бога твого.","І як радів Господь, роблячи вам добро і розмножуючи вас, так буде радіти Господь, гублячи вас і знищуючи вас, і вивержені будете з землі, в яку ти йдеш, щоб володіти нею.","І розсіє тебе Господь [Бог твій] по всіх народах, від краю землі до краю землі, і будеш там служити іншим богам, яких не знав ні ти, ні батьки твої, дереву і камінню.","Але і між цими народами не заспокоїшся, і не буде місця спокою для ноги твоєї, і Господь дасть тобі там тремтяче серце, болість очей і знемагання душі;","життя твоє буде висіти перед тобою, і будеш тремтіти вночі і вдень, і не будеш впевнений у житті твоєму;","від тремтіння серця твого, яким ти будеш обійнятий, і від того, що ти будеш бачити очима твоїми, вранці ти скажеш: «о, якби прийшов вечір », а ввечері скажеш: «о, якби настав ранок!»","і поверне тебе Господь у Єгипет на кораблях тим шляхом, про який я сказав тобі: «ти більше не побачиш його»; і там будете продаватися ворогам вашим у рабів і в рабинь, і не буде того, хто купує."],"x":{"1":"2.26.3","2":"4.11.20|4.14.29|4.23.20","3":"4.30.9","6":"25.120.8","7":"2.26.7","8":"2.25.21|4.15.10","9":"4.7.6|4.29.13","10":"31.43.7|32.14.9|32.15.16","11":"4.30.9","12":"2.26.4|4.14.29|4.15.6","14":"4.5.32|4.8.19|5.1.7","15":"2.26.14|33.2.17|37.9.11|49.2.2|35.2.10","20":"6.2.15","21":"2.26.16|36.14.21","22":"10.8.37","23":"2.26.19","25":"2.26.17|13.29.8|32.15.4","26":"32.7.33","27":"1.9.9","28":"62.1.28","29":"24.5.14|31.59.10","30":"9.12.11|32.6.12|2.26.16","33":"6.6.3|32.5.17","35":"31.1.6","36":"4.4.28","37":"10.9.7|32.24.9|36.5.15","38":"43.6.15|47.1.6","40":"39.1.10","41":"38.9.12","47":"4.31.20|4.32.15|17.9.26","48":"32.28.14|33.5.8","49":"32.5.15|38.8.1|31.33.19","50":"33.5.12|37.8.23","52":"52.19.43","53":"2.26.29|11.6.28-29|33.2.20","58":"55.2.10","59":"36.7.7","60":"1.8.5|4.7.15","62":"4.4.27|4.10.22","63":"31.1.24|46.3.17|26.1.26","64":"4.4.27|17.1.8|32.9.16","66":"48.12.10|76.1.7|25.21.16","68":"38.9.3|4.17.16|32.17.4"}},{"v":["Ось слова завіту, який Господь повелів Мойсеєві укласти із синами Ізраїлевими в землі Моавитській, крім завіту, який Господь поставив з ними на Хориві.","І скликав Мойсей усіх [синів] Ізраїлевих і сказав їм: ви бачили все, що зробив Господь перед очима вашими в землі Єгипетській з фараоном і всіма рабами його і всією землею його;","ті великі кари, які бачили очі твої, і ті великі знамення і чудеса, [руку міцну і могутню силу];","але до цього дня не дав вам Господь [Бог] серця, щоб розуміти, очей, щоб бачити, і вух, щоб чути.","Сорок років водив вас по пустелі, і одяг ваш на вас не зітлів, і взуття твоє не зітліло на ногах твоїх;","хліба ви не їли і вина і сикера не пили, щоб ви знали, що Я Господь Бог ваш.","І коли ви прийшли на місце це, виступив проти нас Сигон, цар Есевонський, і Ог, цар Васанський, щоб воювати з нами, і ми подолали їх;","і взяли землю їхню і віддали її в наділ коліну Рувимовому і Гадовому і половині коліна Манассіїного.","Дотримуйте ж [усіх] слів завіту цього і виконуйте їх, щоб вам мати успіх у всьому, що будете робити.","Усі ви сьогодні стоїте перед лицем Господа Бога вашого, начальники колін ваших, старійшини ваші, [судді ваші,] наглядачі ваші, всі ізраїльтяни,","діти ваші, дружини ваші і прибульці твої, що знаходяться в стані твоєму, від того, хто коле дрова твої, до того, хто черпає воду твою,","щоб увійти тобі в завіт Господа Бога твого й у клятвений договір з Ним, який Господь Бог твій сьогодні укладає з тобою,","щоб зробити тебе сьогодні Його народом, і Йому бути твоїм Богом, як Він говорив тобі і як клявся батькам твоїм Аврааму, Ісааку та Якову.","Не тільки з вами одними я поставляю цей завіт і цей клятвений договір,","але як з тими, які сьогодні тут з нами стоять перед лицем Господа Бога нашого, так і з тими, яких немає тут з нами сьогодні.","Тому що ви знаєте, як ми жили в землі Єгипетській і як ми проходили посеред народів, через які ви пройшли,","і бачили мерзоти їхні й ідолів їхніх, дерев’яних і кам’яних, срібних і золотих, які у них.","Нехай не буде між вами чоловіка або жінки, або роду, або коліна, серце яких ухилилося б нині від Господа Бога нашого, щоб ходити служити богам тих народів; нехай не буде між вами кореня, що вирощує отруту і полин,","такої людини, яка, почувши слова прокляття цього, похвалялася б у серці своєму, говорячи: «я буду щасливий, незважаючи на те, що буду ходити за свавільністю серця мого»; і пропаде в такий спосіб ситий з голодним;","не простить Господь такому, але негайно запалає гнів Господа і лють Його на таку людину, і впаде на нього все прокляття [завіту цього], написане в цій книзі [закону], і зітре Господь ім’я його з піднебесної;","і відокремить його Господь на погибель від усіх колін Ізраїлевих, згідно з усіма прокляттями завіту, написаними в цій книзі закону.","І скаже наступний рід, діти ваші, які будуть після вас, і чужинець, який прийде з землі далекої, побачивши поразку землі цієї і хвороби, якими виснажить її Господь:","сірка і сіль, пожарище — вся земля; не засівається і не вирощує вона, і не виходить на ній ніяка трава, як після знищення Содома, Гоморри, Адми і Севоїма, які знищив Господь у гніві Своєму й у люті Своїй.","І скажуть усі народи: за що Господь так учинив із цією землею? яка велика лють гніву Його!","І скажуть: за те, що вони залишили завіт Господа Бога батьків своїх, який Він уклав з ними, коли вивів їх із землі Єгипетської,","і пішли і стали служити іншим богам і поклонятися їм, богам, яких вони не знали і яких Він не призначав їм:","за те запалав гнів Господа на землю цю, і навів Він на неї всі прокляття [завіту], написані в цій книзі [закону],","і вивергнув їх Господь із землі їх у гніві, люті й великому обуренні, і кинув їх на іншу землю, як нині бачимо.","Приховане належить Господу Богу нашому, а відкрите — нам і синам нашим довіку, щоб ми виконували всі слова закону цього."],"x":{"1":"4.5.2","2":"1.19.4","3":"4.4.34|4.7.15","4":"66.4.18|31.6.9-10","5":"4.8.2","7":"4.3.1|3.21.33","8":"3.21.24|3.32.33|5.13.8","11":"5.9.27","13":"0.12.2|0.17.7|11.13.23","14":"4.5.3|5.24.25","15":"54.2.39","18":"75.12.15","19":"31.66.3:5|32.44.16-18|48.11.5","20":"57.2.20|75.6.8|4.28.15","23":"0.19.25","24":"10.9.8|32.22.8","25":"10.9.8-9|13.7.21-22|32.22.8","26":"5.24.20","29":"71.3.16|25.24.14"}},{"v":["Коли прийдуть на тебе всі слова ці — благословення і прокляття, які виклав я тобі, і приймеш їх до серця свого серед усіх народів, у яких розсіє тебе Господь Бог твій,","і звернешся до Господа Бога твого і послухаєш голосу Його, як я заповідаю тобі сьогодні, ти і сини твої від усього серця твого і від усієї душі твоєї, —","тоді Господь Бог твій поверне полонених твоїх і змилосердиться над тобою, і знову збере тебе від усіх народів, між якими розсіє тебе Господь Бог твій.","Хоча б ти був розсіяний [від краю неба] до краю неба, і звідти збере тебе Господь Бог твій, і звідти візьме тебе,","і [звідти] приведе тебе Господь Бог твій у землю, якою володіли батьки твої, і одержиш її у володіння, і облагодіє тебе і розмножить тебе більше за батьків твоїх;","і обріже Господь Бог твій серце твоє і серце нащадків твоїх, щоб ти любив Господа Бога твого від усього серця твого і від усієї душі твоєї, щоб жити тобі;","тоді Господь Бог твій усі прокляття ці оберне на ворогів твоїх і ненависників твоїх, які гнали тебе,","а ти навернешся і будеш слухати голосу Господа [Бога твого] і виконувати всі заповіді Його, які заповідаю тобі сьогодні;","з надлишком дасть тобі Господь Бог твій успіх у всякій справі рук твоїх, в плоді утроби твоєї, у плоді худоби твоєї, у плоді землі твоєї; бо знову буде радіти Господь [Бог твій] за тебе, благодіючи тобі, як Він радів за батьків твоїх,","якщо будеш слухати голосу Господа Бога твого, дотримуючи [і виконуючи всі] заповіді Його і постанови Його [і закони Його], написані в цій книзі закону, і якщо навернешся до Господа Бога твого всім серцем твоїм і всією душею твоєю.","Бо заповідь ця, яку я заповідаю тобі сьогодні, не недоступна для тебе і не далека;","вона не на небі, щоб можна було говорити: «хто зійшов би для нас на небо і приніс би її нам, і дав би нам почути її, і ми виконали б її?»","і не за морем вона, щоб можна було говорити: «хто сходив би для нас за море і приніс би її нам, і дав би нам почути її, і ми виконали б її?»","але дуже близько до тебе слово це: воно в устах твоїх і в серці твоєму, щоб виконувати його.","Ось, я сьогодні запропонував тобі життя і добро, смерть і зло.","[Якщо будеш слухати заповіді Господа Бога твого,] які заповідаю тобі сьогодні, любити Господа Бога твого, ходити [усіма] путями Його і виконувати заповіді Його і постанови Його і закони Його, то будеш жити і розмножишся, і благословить тебе Господь Бог твій на землі, в яку ти йдеш, щоб оволодіти нею;","якщо ж відвернеться серце твоє, і не будеш слухати, і заблудиш, і станеш поклонятися іншим богам і будеш служити їм,","то я сповіщаю вам сьогодні, що ви загинете і не пробудете довго на землі, [яку Господь Бог дає тобі,] для оволодіння якою ти переходиш Йордан.","У свідки перед вами прикликаю сьогодні небо і землю: життя і смерть запропонував я тобі, благословення і прокляття. Обери життя, щоб жив ти і нащадки твої,","любив Господа Бога твого, слухав голос Його і приліплювався до Нього; бо в цьому життя твоє і довгота днів твоїх, щоб перебувати тобі на землі, яку Господь [Бог] із клятвою обіцяв батькам твоїм Аврааму, Ісааку та Якову дати їм."],"x":{"1":"4.28.9:15","2":"25.105.45","3":"32.23.3|32.29.14","4":"16.1.30|22.1.29","6":"25.50.12|32.4.4|54.7.51","9":"4.28.3:11|32.32.41","11":"31.45.19|31.48.16","12":"62.10.6","15":"4.11.26|4.28.2|30.15.17","17":"2.26.14|4.28.15","18":"4.4.26|4.8.19|4.11.17","19":"4.4.26|31.1.2|32.21.8","20":"4.4.40|53.6.27|0.50.24"}},{"v":["І пішов Мойсей, і говорив слова ці всім [синам] Ізраїля,","і сказав їм: тепер мені сто двадцять років, я не можу уже виходити і входити, і Господь сказав мені: «ти не перейдеш Йордан цей»;","Господь Бог твій Сам піде перед тобою; Він знищить народи ці від імені твого, і ти оволодієш ними; Ісус піде перед тобою, як говорив Господь;","і вчинить Господь з ними так само, як Він зробив із Сигоном і Огом, царями аморрейськими, [які були по цей бік Йордану,] і з землею їх, яких Він знищив;","і видасть їх Господь вам, і ви зробите з ними за всіма заповідями, які заповів я вам;","будьте тверді і мужні, не бійтеся, [не жахайтеся] і не страшіться їх, бо Господь Бог твій Сам піде з тобою [і] не відступить від тебе і не залишить тебе.","І прикликав Мойсей Ісуса і перед очима всіх ізраїльтян сказав йому: будь твердим і мужнім, бо ти ввійдеш з народом цим у землю, яку Господь клявся батькам його дати йому, і ти розділиш її на наділи йому;","Господь Сам піде перед тобою, Сам буде з тобою, не відступить від тебе і не залишить тебе, не бійся і не жахайся.","І написав Мойсей закон цей, і віддав його священикам, синам Левіїним, які носять ковчег завіту Господнього, і всім старійшинам [синів] Ізраїлевих.","І заповів їм Мойсей і сказав: після закінчення семи років, у рік відпущення, у свято кущів,","коли весь Ізраїль прийде явитися перед лицем Господа Бога твого на місці, яке обере [Господь], читай цей закон перед усім Ізраїлем для слуху його;","збери народ, чоловіків і дружин, і дітей, і прибульців твоїх, які будуть в оселях твоїх, щоб вони слухали й училися, і щоб боялися Господа Бога вашого, і намагалися виконувати всі слова закону цього;","і сини їхні, які не знають цього, почують і навчаться боятися Господа Бога вашого в усі дні, доки ви будете жити на землі, в яку ви переходите за Йордан, щоб оволодіти нею.","І сказав Господь Мойсеєві: ось, дні твої наблизилися до смерти; поклич Ісуса і станьте біля [входу] в скинію зібрання, і Я дам йому настанови. І прийшли Мойсей та Ісус, і стали біля [входу] в скинію зібрання.","І явився Господь у скинії в стовпі хмарному, і став стовп хмарний біля входу до скинії [зібрання].","І сказав Господь Мойсеєві: ось, ти упокоїшся з батьками твоїми, і стане народ цей блудно ходити услід за чужими богами тієї землі, в яку він вступає, і залишить Мене, і порушить завіт Мій, який Я уклав з ним;","і запалає гнів Мій на нього в той день, і Я залишу їх і сховаю лице Моє від них, і він знищений буде, і спостигнуть його багато бід і скорбот, і скаже він у той день: «чи не тому спостигли мене ці біди, що немає [Господа] Бога мого серед мене?»","і Я сховаю лице Моє [від нього] у той день за всі беззаконня його, які він зробить, навернувшись до інших богів.","Отже, напишіть собі [слова] пісні цієї, і навчи її синів Ізраїлевих, і вклади її у вуста їхні, щоб пісня ця була Мені свідченням на синів Ізраїлевих;","тому що Я введу їх у землю [добру], як Я клявся батькам їх, де тече молоко і мед, і вони будуть їсти і насичуватися, і потовстішають, і навернуться до інших богів, і будуть служити їм, а Мене відкинуть і порушать завіт Мій, [який Я заповів їм];","і коли прийде на них багато бід і скорбот, тоді пісня ця буде проти них свідченням, бо вона не вийде [з вуст їхніх і] з вуст нащадків їхніх. Я знаю думки їхні, які вони мають нині, раніше ніж Я ввів їх у [добру] землю, про яку Я клявся [батькам їхнім].","І написав Мойсей пісню цю в той день і навчив її синів Ізраїлевих.","І заповів Господь Ісусові, синові Навина, і сказав [йому]: будь твердим і мужнім, бо ти введеш синів Ізраїлевих у землю, про яку Я клявся їм, і Я буду з тобою.","Коли Мойсей вписав у книгу всі слова закону цього до кінця,","тоді Мойсей повелів левитам, які носять ковчег завіту Господнього, сказавши:","візьміть цю книгу закону і покладіть її праворуч ковчега завіту Господа Бога вашого, і вона буде там свідченням проти тебе;","бо я знаю впертість твою і жорстокість твою: ось і тепер, коли я живу з вами нині, ви вперті перед Господом; чи не тим більше після смерти моєї?","зберіть до мене усіх старійшин колін ваших [і суддів ваших] і наглядачів ваших, і я скажу їм уголос слова ці і закличу у свідчення на них небо і землю;","бо я знаю, що після смерти моєї ви розбеститеся й ухилитеся від путі, яку я заповів вам, і з часом прийдуть на вас біди за те, що ви будете робити зло перед очима Господа [Бога], дратуючи Його ділами рук своїх.","І виголосив Мойсей уголос, щоб почуло все зібрання ізраїльтян слова пісні цієї до кінця:"],"x":{"2":"4.1.37|4.3.27|4.4.21","3":"4.7.1","4":"3.21.24","5":"4.7.1-2","6":"4.7.21","7":"3.27.18:22|4.1.29|5.1.1:6","8":"5.1.5","10":"2.23.34|2.25.10|17.8.18","11":"17.8.1|17.13.1|5.8.35","12":"27.12.1","14":"3.20.24|3.27.13|31.38.1","15":"1.33.9|3.9.17|25.98.7","16":"9.7.12|10.1.21|53.11.11","17":"38.2.6","18":"4.32.20","19":"76.15.3","20":"0.50.24|4.28.47|4.32.15|40.5.25-26|54.7.42-43","21":"25.138.2","23":"5.1.6","24":"11.22.8","27":"51.10.5","28":"4.4.26"}},{"v":["Слухай, небо, я буду говорити; і слухай, земле, слова вуст моїх.","Поллється як дощ вчення моє, як роса мова моя, як дрібний дощ на зелень, як злива на траву.","Ім’я Господа прославляю; віддайте славу Богу нашому.","Він твердиня; досконалі діла Його, і всі путі Його праведні; Бог вірний, і немає неправди [у Ньому]; Він праведний і істинний;","але вони розбестилися перед Ним, вони не діти Його за своїми пороками, рід непокірливий і розбещений.","Чи цим відплачуєте ви Господу, народе безглуздий і нерозумний? чи не Він Отець твій, Який привласнив тебе, створив тебе і влаштував тебе?","Згадай дні давні, подумай про роки попередніх родів; запитай батька твого, і він розповість тобі, старців твоїх, і вони скажуть тобі.","Коли Всевишній давав наділи народам і розселяв синів людських, тоді поставив межі народів за числом синів Ізраїлевих*;","бо частина Господа — народ Його, Яків спадкоємний наділ Його.","Він знайшов його в пустелі, у степу сумному і дикому, оберігав його, дивився за ним, оберігав його, як зіницю ока Свого;","як орел прикликає гніздо своє, носиться над пташенятами своїми, простягає крила свої, бере їх і носить на крилах своїх,","так Господь один водив його, і не було з Ним чужого бога.","Він підніс його на висоту землі і годував плодами полів, і поїв його медом з каменю і єлеєм з твердої скелі,","маслом коров’ячим і молоком овечим, і жиром агнців і баранів васанських і козлів, і повною пшеницею, і ти пив вино, кров виноградних ягід.","І [їв Яків, і] розповнішав Ізраїль, і став упертим; розповнішав, потовстішав і розжирів; і залишив він Бога, Який створив його, і знехтував твердиню спасіння свого.","Богами чужими вони роздратували Його і мерзотами [своїми] розгнівали Його:","приносили жертви бісам, а не Богу, богам, яких вони не знали, новим, які прийшли від сусідів і про яких не помишляли батьки ваші.","А Заступника, Який породив тебе, ти забув, і не пам’ятав Бога, Який створив тебе.","Господь побачив [і обурився], і в обуренні зневажив синів Своїх і дочок Своїх,","і сказав: сховаю лице Моє від них [і] побачу, який буде кінець їх; бо вони рід розбещений; діти, у яких немає вірности;","вони роздратували Мене тим, що не є богом, марнотами своїми засмутили Мене: і Я роздратую їх тим, що не є народом, народом безглуздим засмучу їх;","бо вогонь запалав у гніві Моєму, палить до пекла глибинного, і поглинає землю і плоди її, і спалює основи гір;","зберу на них біди і випущу на них стріли Мої:","будуть виснажені голодом, знищені гарячкою і лютою заразою; і пошлю на них зуби звірів і отруту плазунів, що на землі;","ззовні буде губити їх меч, а в домах жах — і юнака, і дівчину, і немовля, і вкритого сивиною старця.","Я сказав би: розсію їх і зітру з середовища людей пам’ять про них;","але відклав це заради озлоблення ворогів, щоб вороги його не загордилися і не сказали: наша рука висока, і не Господь зробив усе це.","Тому що вони народ, який утратив розум, і немає в них сенсу.","О, якби вони розсудили, подумали про це, зрозуміли, що з ними буде!","Як би міг один переслідувати тисячу і двоє проганяти десять тисяч, якби Заступник їх не зрадив їх, і Господь не віддав їх!","Бо заступник їх не такий, як наш Заступник; самі вороги наші судді в тім.","Бо виноград їх від виноградної лози содомської і з полів гоморрських; ягоди їх ягоди отруйні, грона їх гіркі;","вино їх отрута драконів і згубна отрута аспидів.","Чи не приховано це в Мене? чи не запечатано в сховищах Моїх?","У Мене помста і нагорода, коли похитне нога їх; бо близько день загибелі їх, скоро настане приготоване для них.","Але Господь буде судити народ Свій і над рабами Своїми змилосердиться, коли Він побачить, що рука їх ослабла, і не стало ні ув’язнених, ні тих, що залишилися зовні.","Тоді скаже [Господь]: де боги їх, твердиня, на яку вони надіялися,","які їли жир жертв їх [і] пили вино узливань їх? нехай вони повстануть і допоможуть вам, нехай будуть для вас покровом!","Бачите нині, [бачите,] що це Я, Я — і немає Бога, крім Мене: Я умертвляю й оживляю, Я уражаю і Я зціляю, і ніхто не визволить від руки Моєї.","Я піднімаю до небес руку Мою і [клянуся правицею Моєю і] говорю: живу Я повік!","Коли загострю блискучий меч Мій, і рука Моя прийме суд, то відомщу ворогам Моїм і ненависникам Моїм воздам;","напою стріли Мої кров’ю, і меч Мій насититься плоттю, кров’ю убитих і полонених, головами начальників ворога.","[Веселіться, небеса, разом з Ним, і поклоніться Йому, всі ангели Божі.] Веселіться, язичники, з народом Його [і хай зміцняться всі сини Божі]! бо Він відомстить за кров рабів Своїх, і відплатить помстою ворогам Своїм, [і ненависникам Своїм воздасть,] і очистить [Господь] землю Свою і народ Свій!","[І написав Мойсей пісню цю в той день, і навчив її синів Ізраїлевих.] І прийшов Мойсей [до народу] й оголосив усі слова пісні цієї гучно народу, він і Ісус, син Навина.","Коли Мойсей оголосив усі слова ці всьому Ізраїлю,","тоді сказав їм: покладіть на серце ваше всі слова, які я оголосив вам сьогодні, і заповідайте їх дітям своїм, щоб вони намагалися виконувати всі слова закону цього;","бо це не пусте для вас, але це життя ваше, і через це ви довгий час пробудете на тій землі, в яку ви йдете через Йордан, щоб оволодіти нею.","І говорив Господь Мойсеєві в той же самий день і сказав:","зійди на цю гору Аварим, на гору Нево, що в землі Моавитській, навпроти Єрихона, і подивися на землю Ханаанську, яку Я даю у володіння синам Ізраїлевим;","і помри на горі, на яку ти зійдеш, і прилучись до народу твого, як помер Аарон, брат твій, на горі Ор, і прилучився до народу свого,","за те, що ви згрішили проти Мене серед синів Ізраїлевих при водах Мериви в Кадесі, у пустелі Син, за те, що не явили святости Моєї серед синів Ізраїлевих;","перед собою ти побачиш землю, а не ввійдеш туди, у землю, яку Я даю синам Ізраїлевим."],"x":{"1":"4.31.28|17.9.27|31.1.2","2":"31.55.10","3":"76.14.7","4":"9.22.2|63.1.9","5":"31.1.4","6":"50.6.9","7":"25.76.12","8":"0.11.8|54.17.26","9":"8.10.1|9.14.16","10":"38.13.5","11":"1.19.4","12":"1.13.21","13":"4.33.29|3.20.8|8.14.26","14":"32.5.7","15":"4.31.20|38.8.13|31.17.10","17":"25.105.37","18":"35.4.8","20":"4.31.18|26.14.12","21":"62.10.19","22":"32.15.14","24":"45.2.17","25":"33.1.20","29":"32.9.12","30":"2.26.8|38.14.10","32":"0.18.20|31.1.9|31.17.10|32.23.14","35":"30.8.1|62.12.19|75.10.30","36":"25.134.14","37":"10.18.27|32.2.28","38":"2.3.17","39":"4.4.35|31.45.5|8.2.6|18.13.2|29.16.13","40":"0.22.16|32.10.10","43":"62.15.10|3.14.9|31.11.11","44":"22.7.6","47":"31.38.16|1.20.12|4.11.9","49":"3.27.12-13","50":"3.20.25|3.33.38","51":"3.20.12|3.27.14|25.80.8"},"n":{"8":["У грецькому перекладі: за числом ангелів Божих."]}},{"v":["Ось благословення, яким Мойсей, людина Божа, благословив синів Ізраїлевих перед смертю своєю.","Він сказав: Господь прийшов від Синая, відкрився їм від Сеїра, засяяв від гори Фарана і йшов з безліччю святих; праворуч Нього вогонь закону.","Істинно Він любить народ [Свій]; усі святі його в руці Твоїй, і вони припали до ніг Твоїх, щоб слухати слова Твої.","Закон дав нам Мойсей, насліддя громади Якова.","І він був царем Ізраїля, коли збиралися глави народу разом з колінами Ізраїлевими.","Нехай живе Рувим і нехай не вмирає, і [Симеон] нехай не буде нечисленним!","Але про Іуду сказав це: почуй, Господи, голос Іуди і приведи його до народу його; руками своїми нехай захистить він себе, і Ти будь помічником проти ворогів його.","І про Левія сказав: тумим Твій і урим Твій на святому мужі Твоєму, якого Ти випробував у Массі, з яким Ти сперечався при водах Мериви,","який говорить про батька свого і матір свою: «я на них не дивлюся», і братів своїх не визнає, і синів своїх не знає; бо вони, левити, слова Твої зберігають і завіту Твого дотримують,","навчають законів Твоїх Якова і заповідей Твоїх Ізраїля, покладають куріння перед лицем Твоїм і всепалення на жертовник Твій;","благослови, Господи, силу його і до діл рук його благоволи, врази стегна тих, що повстають на нього і ненавидять його, щоб вони не могли стояти.","Про Веніаміна сказав: улюблений Господом живе у Нього безпечно, [Бог] покриває його кожного дня, і він спочиває між раменами Його.","Про Йосифа сказав: нехай благословить Господь землю його жаданими дарами неба, росою і дарами безодні, яка лежить внизу,","жаданими плодами від сонця і жаданими плодами місяця,","чудовими плодами гір древніх і жаданими дарами пагорбів вічних,","і жаданими дарами землі і того, що наповнює її; благословення Того, Хто явився у терновому кущі, нехай прийде на голову Йосифа і на тім’я найкращого з братів своїх;","міцність його як первородного тельця, і роги його, як роги буйвола; ними колотиме він народи усі до країв землі: це десятки тисяч Єфремові, це тисячі Манассіїні.","Про Завулона сказав: веселися, Завулоне, в путях твоїх, і Іссахаре, в наметах твоїх;","скликають вони народ на гору, там заколюють законні жертви, бо вони годуються багатством моря і скарбами, прихованими в піску.","Про Гада сказав: благословенний, той, хто розповсюдив Гада, він спочиває як лев і розтрощує і м’язи і голову;","він обрав собі початок землі, там ушанований наділом від законодавця, і прийшов із главами народу, і виконав правду Господа і суди з Ізраїлем.","Про Дана сказав: Дан молодий лев, який вибігає з Васана.","Про Неффалима сказав: Неффалим насичений благоволінням і сповнений благословення Господа; море і південь у володінні його.","Про Асира сказав: благословенний між синами Асир, він буде любимим братами своїми, і занурить у єлей ногу свою;","залізо і мідь — запори твої; як дні твої, буде примножуватися багатство твоє.","Немає подібного до Бога Ізраїлевого, Який по небесах принісся на допомогу тобі й у славі Своїй на хмарах;","притулок [твій] Бог превічний, і [ти] на раменах вічних; Він прожене ворогів від лиця твого і скаже: знищуй!","Ізраїль живе безпечно, один; око Якова бачить перед собою землю, повну хліба і вина, і небеса його викраплюють росу.","Блаженний ти, Ізраїлю! хто подібний до тебе, народе, що охороняється Господом, Який є щитом, що охороняє тебе, і мечем слави твоєї? Вороги твої раболіпствують перед тобою, і ти зневажаєш гордість їх."],"x":{"1":"30.3.8-9","2":"6.5.4|25.67.18|45.3.3","3":"29.3.1","4":"25.147.8","6":"0.49.3","7":"0.49.10|75.7.14","8":"1.17.7|1.28.30|3.20.13","9":"1.32.27-28|50.4.22|50.10.37","12":"5.18.11","13":"0.27.28|0.49.22-25","16":"1.3.2","17":"3.23.22|0.48.19-20","19":"25.50.19:21","20":"0.49.19","22":"5.19.47","23":"0.49.21","24":"5.19.24","28":"32.23.6|32.33.16","29":"9.7.10|25.65.3"}},{"v":["І зійшов Мойсей з рівнин моавитських на гору Нево, на вершину Фасги, яка навпроти Єрихона, і показав йому Господь усю землю Галаад до самого Дана,","і всю [землю] Неффалимову, і [всю] землю Єфремову і Манассіїну, і всю землю Іудину, навіть до самого західного моря,","і полуденну країну і рівнину долини Єрихона, місто Пальм, до Сигора.","І сказав йому Господь: ось земля, про яку Я клявся Аврааму, Ісааку та Якову, говорячи: «сімені твоєму дам її»; Я дав тобі побачити її очима твоїми, але в неї ти не ввійдеш.","І помер там Мойсей, раб Господній, на землі Моавитській, за словом Господнім;","і був похований у долині в землі Моавитській навпроти Беф-Фегора, і ніхто не знає місця поховання його навіть до цього дня.","Мойсеєві було сто двадцять років, коли він помер; але зір його не притупився, і міцність у ньому не виснажилася.","І оплакували Мойсея сини Ізраїлеві на рівнинах моавитських [навпроти Йордану біля Єрихона] тридцять днів. І минули дні плачу і ридання за Мойсеєм.","І Ісус, син Навина, сповнився духом премудрости, тому що Мойсей поклав на нього руки свої, і підкорювалися йому сини Ізраїлеві і робили так, як повелів Господь Мойсеєві.","І не було більше в Ізраїля пророка такого, як Мойсей, якого Господь знав лицем до лиця,","за всіма знаменнями і чудесами, які послав його Господь зробити в землі Єгипетській над фараоном і над усіма рабами його і над усією землею його,","і за рукою сильною і за великими чудесами, які Мойсей звершив перед очима усього Ізраїля."],"x":{"1":"22.2.4","3":"11.2.4-5|0.19.22","4":"4.4.21|0.12.7|0.13.15|0.15.18|0.26.3","5":"3.20.12|5.24.29","6":"4.32.50|61.1.9","7":"4.31.2","8":"3.20.29","9":"54.8.17|3.27.18","10":"50.12.41|1.33.11|3.12.8"}}];
